(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["3-4"] = [{"a": [145], "v": 3, "p": 892, "ev": 3, "ep": 896, "sid": 1093, "t": "قوله تعالى: (وما كان لنفس أن تموت إلا بإذن الله كتابا مؤجلا ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الآخرة نؤته منها وسنجزي الشاكرين (145).\n⟦3:893⟧\nاللام في قوله: ﴿وَمَا كَانَ لِنَفۡسٍ﴾⟪3:145⟫ على سبيل نسبة الانفعال إلى المنفعل، كقولك: الموت للنفس والنسج للثوب، ولما توهم المنافقون أن القتل غير\nالموت، وأن الإنسان سيجد سبيلا إلى الخلاص منه، ولم يتصوروا\nتقدير الله وأن ذلك مقضي لا انفكاك منه، حتى قالوا: ﴿لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ﴾⟪3:168⟫، بين تعالى أن الموت شيء مقضي محكوم به، وهذا\nمعنى (كتابا مؤجلا)، فلا تأخير له، ودل على ذلك بآيات الله.\nنحو قوله تعالى: ﴿لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ﴾⟪33:16⟫\nوقوله: ﴿فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ﴾.\nوقوله: ﴿أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ﴾⟪4:78⟫\n⟦3:894⟧\nوقوله في هذه السورة: ﴿يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ﴾⟪3:154⟫\nوعلى ذلك قول الشاعر:\n. . . أن الفرار لا يزيد في الأجل\nولما كان أكثر الأعمال مشتبه الصور، وإنما يتميز الخبيث من\nالطيب بالنيات، ولهذا قال - صلى الله عليه وسلم -: \"الأعمال بالنيات ولكل امرئ ما نوى فمن كانت هجرته إلى الله ورسوله \" الخبر.\nوالمجاهد في سبيل الله ثلاثة:\nإما قاصد به الآخرة غير ملتفت إلى الدنيا،\n⟦3:895⟧\nوإما قاصد عرضا دنيويا مراعيا فيه حكم النه على ما ورد الأمر في\nقوله: ﴿وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ﴾⟪62:10⟫.\nوإما قاصد عرضا دنيويا غير مراع فيه حكم الله على ما دل عليه قوله: ﴿مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ﴾⟪11:15⟫ فسر على الوجهين:\nأحدهما: أن لفظ الثواب ههنا على التوسع، وإنما هو على نحو الحرث في\nقوله: ﴿مَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ وَمَن كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِن نَّصِيبٍ﴾⟪42:20⟫\nويكون المعنى على نحو ما بينه في قوله: ﴿مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ﴾⟪17:18⟫.\nوالثاني: أن الثواب هو الذي يحصل للإنسان ولا يلحقه فيه تبعة.\nفالمراد به ما ذكره في قوله:\n⟦3:896⟧\n﴿وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ﴾⟪62:10⟫، وقوله - صلى الله عليه وسلم -:\n\"من طلب الدنيا استعفافا عن المسألة، وسعيا على أهله، بعثه الله ووجهه كالقمر \".\nوقو له: (وسنجزي الشاكرين) قد تقدم الكلام فيه."}, {"a": [146], "v": 3, "p": 896, "ev": 3, "ep": 899, "sid": 1097, "t": "قوله تعالى: (وكأين من نبي قاتل معه ربيون كثير فما وهنوا لما أصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصابرين (146).\nكأين: بمعنى كم، وأصله أي دخله الكاف، والنون في\n⟦3:897⟧\nآخره هو التنوين، قيل: وإذا وقف يقال كأي على قول من قال\nمررت بزيد، وكأيى على قول من قال بزيدي، وقال بعض\nالنحويين: يجوز أن يقال كأين في الوقف، لأنه لما تركبا صار التنوين.\nكحرف من الكلمة، كقولهم: رعملي ولعمري.\nوالربي: قيل: التقي العالم المنسوب إلى الرب، وكذلك الرباني وغير في النسبة كقولهم في أمس إمسي، وفي الجمة جماني، وقيل الربيون\nالجماعات الكثيرة، ومنه قيل للجماعة ربة، ولما يجمع فيه القداح\nرباية، والفرق بين الوهن والضعف: أن الوهن إخلال يغير\n⟦3:898⟧\nالإنسان، ويضاده الشدة، والضعف أختلال بنقصه ويضاده\nالقوى، والاستكانة: الخشوع والتضرع للمخافة.\nوقيل: قتل هو فعل مسند إلى قوله: ﴿وَكَأَيِّن مِّن نَّبِيّٖ﴾⟪3:146⟫، \" و (معه ربيون)، استئناف في موضع الحال، كأنه قتل ومعه.\nوقال الحسن: ما قتل نبي قط في حرب.\nوقال بعضهم ما قال الحسن؛\n⟦3:899⟧\nوإن صح فإنه لا ينفي أنه قتل في غير حرب.\nوقيل: إن قوله: (قتل) فعل لقوله (ربيون) أي قتل جماعة منهم، فلم يهن الباقون منهم، ومن قرأ: (قاتل) فيحتمل الوجهين.\nوقوله: ﴿وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ﴾⟪3:146⟫.\nفقد جعلهم محبوبيه تعظيما لقدرهم، وإلى معنى المحبة أشار بقوله:\n﴿إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ﴾، وقوله: ﴿وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ﴾⟪52:48⟫.\nوقال - صلى الله عليه وسلم -: \"الصبر خير كله \".\nوقال: \" الصبر من الإيمان بمنزلة الرأس من الجسد\"."}, {"a": [147], "v": 3, "p": 900, "ev": 3, "ep": 902, "sid": 1101, "t": "قوله تعالى: (وما كان قولهم إلا أن قالوا ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا وثبت أقدامنا وانصرنا على القوم الكافرين (147)\nالفرق بين الدنب والإسراف من وجهين:\nأحدهما: أن الإسراف نجاوز الحد فى فعل ما يجب، والذنب عام فيه وفي التقصير، فإذا كل إسراف ذنب، وليس كل ذنب إسرافا.\nوالثاني: أن حقيقة الذنب: التقصير وترك الأمر حتى يفوت، ثم يؤخذ بالذنب. والذنب إذن في الأصل مقابل الإسراف، وكلاهما مذمومان، أحدهما: من جهة التفريط. والآخر: من جهة الإفراط.\n⟦3:901⟧\nوالمحمود هو العدالة، والقصد المنفك منهما، وثبات القدم في الأمر\nاللزوم، وعلى هذا قوله: ﴿فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا﴾⟪16:94⟫، وكيفية\nتثبيت الأقدام، قيل بإلطاف من جهته، وقيل بإنزال الملائكة\nعليهم، وذلك عام في كل نصرة ينصر الله بها عبده من قوة نفسه.\nومما يعينه من خارج.\nوقيل: أشار بذلك إلى سؤال الصيانة عما يحبط ما تقدم من الأعمال.\nوهذا السؤال نحو ما روي\n⟦3:902⟧\nعن النبي - صلى الله عليه وسلم -: \"يا مقلب القلوب ثبت قلبي على دينك \".\nوالآية هى من جملة الحكاية عن الربيين، وتحقيق لما قال: ﴿أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ﴾ الآية، وحث على الاقتداء بمن\nتقدم في أحوالهم التي وصفوا بها، وهذه الجملة من التضرع إلى\nالله وهو جماع سؤال الخيرات، فقد سألوا الله العفو عنهم فيما\nكان منهم من إفراط وتفريط، والحراسة في أنفسهم ونصرهم\nعلى أعدائهم."}, {"a": [148], "v": 3, "p": 902, "ev": 3, "ep": 905, "sid": 1103, "t": "قوله تعالى: (فآتاهم الله ثواب الدنيا وحسن ثواب الآخرة والله يحب المحسنين (148).\nذكر في ثواب الآخرة الحسن تنبيها أن ثواب الدنيا بالإضافة إليها غير\nمستحسن لانقطاعه، ونبه بالآية أن من أراد ثواب الدنيا\n⟦3:903⟧\nلم يحصل له ثواب الآخرة، وأن من أراد الآخرة حصلت له الدنيا\nوالآخرة معا، وعلى هذا قال - صلى الله عليه وسلم -: \"من كانت همته للدنيا شتت الله عليه أمره، وجعل فقره بين عينيه، ولم يؤته من الدنيا إلا ما كتب له، ومن كانت همته الآخرة جمع الله شمله، وجعل غناه في قلبه، وأتته الدنيا وهي راغمة\"\nوهذا المعنى الذي اقتضاه الخبر ذكره\n⟦3:904⟧\nابن الرومي في قوله:\nوتاجر الأجر لا يزال له. . . أمران كل متجر تجره\nأجر وحمد وإنما قصد ال. . . أجر ولكن كلاهما اعتوره\nوسئل سفيان بن عيينة: هل يعطى المسلم ثواب عمله في\nالدنيا؟ فقال: نعم، وتلا هذه الآية، وقوله تعالى: ﴿وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ﴾⟪16:122⟫.\nوقوله في قصة يوسف: ﴿وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ﴾ الآية، تم\n⟦3:905⟧\nقال: ﴿وَلَأَجۡرُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ءَامَنُواْ﴾⟪12:57⟫ الآية."}, {"a": [149], "v": 3, "p": 905, "ev": 3, "ep": 906, "sid": 1106, "t": "قوله تعالى: (يا أيها الذين آمنوا إن تطيعوا الذين كفروا يردوكم على أعقابكم فتنقلبوا خاسرين (149).\nهذا هو المعنى المذكور في قوله: ﴿إِن تُطِيعُواْ فَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم﴾⟪3:100⟫، لكنه لما ذكر هناك باللفظ العام وهو أهل الكتاب الواقع على مؤمنهم وكافرهم خص فريقا منهم.\nفإن قيل: لم غير العبارتين؟ ولم كرر ذلك؟\nقيل: إنه عرض في الأول بالنهي، فلما بين أحوال المنهي عن\nطاعتهم، ونبه على فساد طريقتهم وإرادتهم الشر بالمسلمين أعاد\nالنهي عن طاعتهم مصرحا، وهذه الطريقة يسلكها الوعظة\nالمهرة، فنهي الإنسان عما يهواه إذا لم يعرف قبحه إغراء بفعله،\n⟦3:906⟧\nفحق للواعظ أن يتوصل أولا إلى كشف قبحه، وما يعرض فيه\nمن الفساد، ثم يصرح بتحريمه، والنفي عنه.\nوقول الحسن: إنه عنى بالذين كفروا: اليهود والنصارى.\nوقول السدي: إنه أراد المشركين أبا سفيان وأصحابه، فكلاهما صحيح.\nفاللفظ عام، ومطاوعتهما ترد على الأعقاب وتورث الخسران."}, {"a": [150], "v": 3, "p": 906, "ev": 3, "ep": 907, "sid": 1107, "t": "قوله تعالى: (بل الله مولاكم وهو خير الناصرين (150)\nلما تقرر في العقول: أن المولى يعز بحسب عزة مواليه.\nوتقرر عند المسلمين أن الله هو العزيز في الحقيقة، وأن كل\nعزيز فمنه وبه يعز، وقد كان نهاهم في الآية المتقدمة عن\nموالاة الكفار، والدخول تحت طاعتهم بين، أن من\n⟦3:907⟧\nكان، الله مولاه فهو غني عنهم فهو خير مولى وناصر.\nوهذا المعنى قد نبه تعالى عليه في مواضع بألفاظ كثيرة، نحو ﴿نِعۡمَ ٱلۡمَوۡلَىٰ﴾، وقوله: ﴿ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِينَ ءَامَنُواْ﴾⟪47:11⟫.\nوفي لفظة بل تلطف وتنبيه أن من المحال أن يكون من تخصص\nبموالاة الله، وعرف أن العز منه أن يعتمد غيره أو يقصد سواه."}, {"a": [151], "v": 3, "p": 907, "ev": 3, "ep": 911, "sid": 1108, "t": "قوله تعالى: (سنلقي في قلوب الذين كفروا الرعب بما أشركوا بالله ما لم ينزل به سلطانا ومأواهم النار وبئس مثوى الظالمين (151)\nالرعب: استرخاء القوى وتقطعها من الخوف، ومنه:\n⟦3:908⟧\nجارية رعبوبة، ورعبت السنام قطعته، وبهذا النظر\nقالوا: تقطع نياط قلبه، وانخلع قلبه، وتوزع خاطره.\nوالسلطان: الحجة، وقد تقدم.\nوالمثوى: إطالة الملازمة.\nوقوله: ﴿بِمَآ أَشۡرَكُواْ﴾⟪3:151⟫ أي إشراكهم،\n⟦3:909⟧\nوقوله: ﴿مَا لَمۡ يُنَزِّلۡ بِهِۦ﴾⟪3:151⟫ بدل من ما الأولى، لكن بمعنى\nالمصدر، إذ لا ضمير يرجع إليه، والثاني بمعنى الذي، إذ\nفيما بعده ضمير، ويجوز أن يكون خبر ابتداء مضمر.\nأو على تقدير: أعني شيئا لم ينزل به سلطانا.\nوالمعنى لا يختلف، ونبه أنه لم يجعل لهم حجة فيما قالوا: ﴿مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ﴾⟪39:3⟫، ولقوله: ﴿سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ﴾⟪3:151⟫، ولظهور حكمه، وما شوهد\n⟦3:910⟧\nمن صدقه. قال - عز وجل -: \"نصرت بالرعب \".\nوتصديق ذلك قد شوهد، فقد كان الصناديد يقصدونه عليه السلام لمكاوحته أو الاغتيال عليه، فما كانوا إلا أن يمكنوا أبصارهم منه فيذلوا.\nولمشاهدة الحالة قال فيه الشاعر:\nلو لم تكن فيه آيات مبينة. . . كانت بداهته تغنيك عن خبر\nوهذا أحد دلائل للنبوات التي يعتمدها من عرف الحقائق.\nوليس هذا الرعب للنبي - صلى الله عليه وسلم - فقط، بل لأحزابه والمقتدين به، حتى نرى من رجح عقله وحسن في قمع الشهوة حاله مهيب.\nوجعل جهنم مثوى مذموما بالإضافة إلى الطباع، واعتبارها\nبكراهتها لها،\n⟦3:911⟧\nوعلى ذلك قوله: ﴿وَسَآءَتۡ مَصِيرًا﴾."}, {"a": [152], "v": 3, "p": 911, "ev": 3, "ep": 918, "sid": 1112, "t": "قوله تعالى: (ولقد صدقكم الله وعده إذ تحسونهم بإذنه حتى إذا فشلتم وتنازعتم في الأمر وعصيتم من بعد ما أراكم ما تحبون منكم من يريد الدنيا ومنكم من يريد الآخرة ثم صرفكم عنهم ليبتليكم ولقد عفا عنكم والله ذو فضل على المؤمنين (152).\nالحس: يقال للإصابة بالحاسة نحو عنته ويديته، أي أصبته بهما.\nويقال تارة لإصابة الحاس نحو بطنته وظهرته، أي أصبتهما.\nولما كان إصابة الحاسة قد يتولد منه فقد الروح استعير للقتل،\n⟦3:912⟧\nوإذنه هاهنا يصح أن يكون أمره، وأن يكون تسهيله وتوفيقه.\nوالفشل: ضعف النجيزة، وذلك يكون عن الحرب، وعن\nالسخاء، بل عن تحمل المضض، وجعل تعالى ميلهم إلى\nالغنيمة فشلا، فإن الحرص والبخل من فشل النجيزة، وسبب\nنزول هذه الآية فيما روي أن النبي - صلى الله عليه وسلم - كان قد وعد المؤمنين بقهر الكفار يوم أحد، ولما صف الصفوف جعل أحدا خلف ظهره.\nواستقبل المدينة، وجعل عينين وهو جبل عن يساره، ورتب\n⟦3:913⟧\nعليه رماة خمسين، واستعمل غليهم عبد الله بن جبير، وأوعز\nإليهم أن قوموا في مصافكم، فإن رأيتمونا وقد غنمنا فلا تشاركونا.\nوإن رأيتمونا نقتل فلا تنصرونا، فلما رأوا الكفار يهزمون.\nاختلفوا فبادر بعض إلى المعركة، ونظر خالد بن الوليد إلى\nالجبل وكان كمينا للمشركين، فكر بالخيل، فقتل من بقي من\nالرماة، وانتقضت صفوف المسلمين حتى كان ما كان، فقال\n⟦3:914⟧\nقوم: إن الله قد وعدنا نصرنا، فتغيرت قلوبهم، فبين تعالى أنه\nقد صدقكم وعده، وأخذتم تقتلونهم إلى أن اعتراكم الفشل.\nووقع بينكم تنازع، فصرفكم عنهم.\nوقوله: ﴿مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا﴾⟪3:152⟫ قيل: الغنيمة.\n﴿وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ﴾⟪3:152⟫ أي نصرة النبي في ترك\nالمكان والمبادرة إلى القتال.\n⟦3:915⟧\nوقيل: بل عنى بمن يريد الآخرة من أقام حافظا لما استحفظ.\nوقوله: ﴿ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ﴾⟪3:152⟫ قيل: صرفهم إنما كان.\nبمنع النصرة وترك إنزال الملائكة عليهم والسكينة، وبإخراج\nما في قلوب الذين كفروا من الرعب، فبين أن لم يكن صرفكم\nعنهم خذلانا لكم، بل كان مؤاخذة لميلكم إلى الدنيا وابتلاء\nلكم، كما بينه بقوله: ﴿وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّٰبِرِينَ﴾⟪3:142⟫\n⟦3:916⟧\nوذكر أنه عفا عما كان منهم من مخالفتهم النبي - صلى الله عليه وسلم -.\nوإخلالهم بالمركز، قال الحسن: عفا عنهم، إذ لم يستأصلهم.\nفقد قتل منهم من قتل، وكسر رباعية الرسول - صلى الله عليه وسلم -، وقيل: (عفا عنكم) حيث عاقبكم في عاجل الدنيا، وأفضل\nعليكم بذلك لكونه موعظة لكم في معاودة مثله)، ثم بين أن\n⟦3:917⟧\nالله ذو فضل في عفوه عنكم في انهزأمكم وفي صرفكم عنهم، الذي\nصار سببا لتهذيبكم وتمحيصكم، وسببا لأن تصيروا مجاهدين\nفي المستقبل، فيعلم الله الذين آمنوا ويتخذ منكم شهداء، فكل\nما هو سبب خير وإن كره ففضل.\nواختلف في جواب (إذا) فقال الفراء: تقديره تنازعتم.\nوالواو مقحمة، قال: وذلك يكثر مع إذا نحو ﴿حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ﴾⟪21:96⟫ وقوله: ﴿حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ﴾⟪39:73⟫ أي: فتحت.\nوقوله: ﴿فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ ۝ وَنَٰدَيۡنَٰهُ﴾⟪37:103-104⟫ أي ناديناه.\nوقال ابن بحر:\nثم صرفكم جواب، وتقديره صرفك، وقال: ودخل (ثم)\n⟦3:918⟧\nفي الكلام، لأنه في المعنى مثل: إذا، وكأنه رد لفظ إذا لما طال\nالكلام، كقوله: ﴿وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ﴾⟪2:89⟫، ثم قال:\n﴿فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ﴾⟪2:89⟫ فأعاد لما لما طال.\nفكذلك القول في (ثم صرفكم) وهذا القول أستطرفه.\nفإني أراه تصور ثم بمعنى ثم على التقدير الذي ذكره.\nوقال البصريون: جوابه في هذه الأمكنة كلها محذوف."}, {"a": [153], "v": 3, "p": 918, "ev": 3, "ep": 927, "sid": 1119, "t": "قوله تعالى: (إذ تصعدون ولا تلوون على أحد والرسول يدعوكم في أخراكم فأثابكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما أصابكم والله خبير بما تعملون (153)\nإذ: متعلق بقوله: (عفا) وبقوله: ﴿ذُو فَضۡلٍ﴾⟪3:152⟫.\nوالإصعاد: الإبعاد في الأرض، سواء كان\n⟦3:919⟧\nفي صعود أو حدور، وإن كان أصله من الصعود كقولهم:\nتعال في أن صار في التعارف، قد يقال لغير معنى العلو.\nوالصعود: الذهاب في صعود. ولما روى قتادة والربيع: أن\n⟦3:920⟧\nمن هرب من المؤمنين ذهبوا في الوادي.\nوروى الحسن أنهم صعدوا في الجبل.\nوقرئ (تصعدون) اعتبارا بالرواية الأولى\nو (تصعدون) اعتبارا بالرواية الثانية، وإنما ذلك باعتبار علو\nالإنسان في أمر تحراه، كقولك: أبعدت في كذا، وارتقيت في\nكذا كل مرتقى، فكأنه قيل: إذ تبعدون في استشعار الخوف،\n⟦3:921⟧\nالاستمرار على الهزيمة.\nوقوله: (ولا تلوون على أحد) تعريض بهم في الهزيمة.\nونحوه تحراه حسان، بقوله.\nترك الأحبة أن يقاتل دونهم. . . ونجا برأس طمرة وثاب\n⟦3:922⟧\nوقرأ الحسن: (ولا تلوون) من ولي.\nوقال بعضهم: هو خطأ.\nووجهه أن ذلك تبكيت لهم، وأنهم لم يلو ما ولو بل أخلوا.\nوقوله: ﴿يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ﴾⟪3:153⟫، أي هو بين جماعة\nالمتأخرين منكم.\nوروي أن رسول الله) مم كان يناديهم: \"يا عباد الله ارجعوا\".\nإن قيل: كيف قال ﴿فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ﴾⟪3:153⟫،\n⟦3:923⟧\nوالإثابة تقال في المحبوب دون المكروه؟!\nقيل: قد قال بعضهم: إن ذلك يستعمل في المكروه على أحد وجهين:\nإما لأن الثواب في الأصل ما يرجع إلى الإنسان من ثمرة فعله خيرا كان أو شرا، ولكن تعورف في الخير، فإذا استعمل في المكروه فعلى اعتبار الأصل.\nوالثاني: أن ذلك على الاستعارة، وضرب من التهكم\nفي كلامهم، كقوله:\n. . . تحيه بينهم ضرب وجيع\n⟦3:924⟧\nوقال بعض المحققين. إنما ذكر لفظ الإثابة هاهنا في الغم، لأن\nغمهم وإن كان مكروها بالطبع فهو ثواب من الله من وجه، لأنه\nكان سبب تهذيب نفوسهم، الذي بينه تعالى بقوله: ﴿لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ﴾⟪57:23⟫، وكل أمر يؤدي بالإنسان إلى أن يجعله بحيث\nلا يقلقه فوت مطلوب وفقد محبوب فيا له من ثواب، ولهذا\nقال حكيم: جماع الزهادة في قوله: ﴿لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ﴾⟪57:23⟫\nفقوله: (غما) من المفسرين\n⟦3:925⟧\nمن اعتبر الغمين بالمسلمين وقال: أحدهما: ما وصل إلى قلوبهم من الفشل.\nوالثاني: الخوف. وقيل: أحدهما: مخالفتهم للنبي - صلى الله عليه وسلم -.\nوالثاني: فوت الغنيمة.\nوقيل: ما سمعوا من قتل النبي - صلى الله عليه وسلم -\nوقيل: إشراف أبي سفيان عليهم.\nوالوجه: أن كل\n⟦3:926⟧\nذلك مراد، لأنه ليس يعني بذلك غمين، بل غموما كثيرة متتابعة\nمتوالية كقولهم: لبيك وقوله: ﴿بَلۡ يَدَاهُ مَبۡسُوطَتَانِ﴾⟪5:64⟫\nأي نعمه متوالية، ومنهم من اعتبر أحد الغمين بالمسلمين\n⟦3:927⟧\nوالآخر بالكافرين. فقال: أنالوكم مثل ما أنلتموهم، تنبيها\nعلى معنى قوله: ﴿وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ﴾⟪3:140⟫\nوقوله: ﴿وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ﴾⟪3:153⟫ أي عالم به يخبركم به، تنبيها\nعلى ما قال: ﴿ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ﴾."}, {"a": [154], "v": 3, "p": 927, "ev": 3, "ep": 939, "sid": 1128, "t": "قوله تعالى: (ثم أنزل عليكم من بعد الغم أمنة نعاسا يغشى طائفة منكم وطائفة قد أهمتهم أنفسهم يظنون بالله غير الحق ظن الجاهلية يقولون هل لنا من الأمر من شيء قل إن الأمر كله لله يخفون في أنفسهم ما لا يبدون لك يقولون لو كان لنا من الأمر شيء ما قتلنا هاهنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل إلى مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور (154)\n⟦3:928⟧\nقرئ (تغشى) ردا على لفظ (أمنة)، و (يغشى) إلى لفظ (نعاسا).\nوقرئ (كله) على الابتداء، و (كله) على التأكيد، وقيل: السبب في\nنزولها أن يوم أحد تواعد المشركون بالرجوع، وكان المسلمون\n⟦3:929⟧\nمتهيئين للقتال، فأنزل الله تعالى على المؤمنين أمنة فنام بعضهم.\nونفى عن المنافقين الأمنة، فسهروا منزعجين، فمن حمل\nالنوم على الحقيقة قال: جعل ذلك رأفة بهم،\n⟦3:930⟧\nوتخصيص النعاس تنبيه على صيانتهم من الحالة المذمومة من\nالامتلاء من النوم، ومنهم من جعله استعاوة لطمأنينة جأشهم.\nوزوال خوفهم، وذلك لما ترى من حال المطمئن، ويوصف\nالمغموم بالسهر، ومنهم من تجاوز ذلك، وقال: إنه لما ذكر في\nالأول قوله: ﴿فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ﴾⟪3:153⟫\nبين هاهنا أنه تعالى هذب طائفة من المؤمنين، حتى صارت نفوسهم آمنة مطمئنة تحت قضاء الله، وهذه حالة الرضى، فقد قيل: الرضى أن يكون العبد ساكنا تحت قضاء الله، مطمئنا عند كل وارد سر أم ساء، وهذه الحال ادعاها الشاعر صادقا أو كاذبا في قوله:\n⟦3:931⟧\nفسر ولم ابتهج. . . وساء ولم أشتكي\nوقوله تعالى: ﴿وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ﴾⟪3:154⟫ تنبيه على\nخبث أنفسهم، وأنها أمارة بالسوء، وذاك أن المنافق شرير.\nوالشرير لم تتهذب نفسه وأحواله من الغضب والشهوة والحرص\nوسائر الرذائل، وكأن ما معه عدو يؤذيه، ولهذا لا يمكنه أن يخلو\nبنفسه، لأنه لا يجد شاغلا له، وكأنه خلي مع أسود وأساود.\nوقوله: ﴿يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ﴾⟪3:154⟫ تنبيه على جهلهم وعدم معرفتهم\nبحكمة الله ونعمته في قهر الكفار للمسلمين في بعض الأحوال.\nوأنها نعمة. وظنهم غير الحق: ظنهم أن النبي - صلى الله عليه وسلم - لم يصدقهم، ويأسهم من نصرة الله تعالى.\nوقوله: ﴿ظَنَّ ٱلۡجَٰهِلِيَّةِۖ﴾⟪3:154⟫ أي ظن\n⟦3:932⟧\nالكفار، أن هؤلاء المنافقين بعد في حيز الكفار، وفي قلة\nمعرفتهم الله بحكمة الله تعالى، وأنهم لا يعرفون الخير والنعمة\nإلا المال والجاه والغلبة الدنيوية، فإذا فاتهم ذلك ساء ظنهم.\nوقوله: ﴿يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ﴾⟪3:154⟫:\nهل لنا طمع الغلبة، تنبيها أنهم استشعروا اليأس الذي يستشعره القوم\nالكافرون، فأكذبهم الله تعالى، فقال: ﴿قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ﴾⟪3:154⟫\nأي الغلبة الحقيقة له ولأوليائه، فإن حزب الله هم الغالبون.\nوقيل: عنى بالأمر الاستئمار، أي لو شوورنا لأشرنا بترك هذا\nالمورد، فقال الله تعالى: ﴿ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ﴾⟪3:154⟫ أي هو أعرف بالتدبير.\n⟦3:933⟧\nوقوله: ﴿يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ﴾⟪3:154⟫\nمعناه لولا أنا أكرهنا لما خرجنا، وفصل بين الحكايتين\nعنهم، أعني (هل لنا) وقوله: (يقولون) بجملتين:\nإحداهما: جواب لهم، وهي قوله: ﴿قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ﴾⟪3:154⟫.\nوالثانية: تنبيه على ما في ضمائرهم، وهي قوله: ﴿يُخۡفُونَ فِيٓ أَنفُسِهِم﴾⟪3:154⟫.\nولما فصل بينهما أعيد في الحكاية عنهم لفظ (يقولون) لئلا تشتبه\nالحكاية عنهم بما هو إخبار منه تعالى،\n⟦3:934⟧\nوقال بعض المعتزلة: عنى بقوله: ﴿يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ﴾⟪3:154⟫\nأنه كقوله: ﴿لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا﴾⟪6:148⟫ وهذا إن كان\nكما قاله هذا القائل، فقوله: ﴿قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ﴾⟪3:154⟫ تصديق لهم.\nوقوله: ﴿قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ﴾⟪3:154⟫\nتكذيب لهم، وأنه محال - أن لا يقتلوأ مع أن قتلهم بذلك المكان\nجار في قضائه وتقديره، وقد حمل ذلك على وجهين: إما أن من\nفدر له القتل لو لم يخرج لأتاه القتل، وهو في مضجعه في داره،\n⟦3:935⟧\nوالثاني: أنه لو كنتم أيها المؤمنون قعدتم في بيوتكم، ولم تخرجوا\nللمحاربة لخرج من قدر له القتل بسبب خفي إلى مضاجعهم في\nالحرب أي مصارعهم فيقتلون، تنبيها أن قضاء الله وتقديره\nوعلمه لا يتغير، وأنه لا ينفع حذر من قدر، وإلى هذا أشار\nالشاعر بقوله:\nإذا ما حمام المرء كان ببلدة. . . دعته إليها حاجة فيطير\nوقال الأصم معناه: لو كنتم أيها المنافقون في بيوتكم، ولم\nتخرجوا لبرز المسلمون الذين كتب عليهم أي أوجب أن يقاتلوا\nمحتسبين، ويكون هذا ثناء من الله تعالى على من استشهد.\nإن قيل: ما حقيقة الابتلاء والفصل بينه وبين المحص؟\n⟦3:936⟧\nقيل: الابتلاء في الأصل هو الاختبار، الذي يفصل به بين الخير والشر\nفهو اسم الفعل مبدأ ونهاية، فمبدؤه الاختبار، ونهايته الفصل بين\nالخير والشر إذا استعمل في الله تعالى، فإنه يراد به النهاية دون\nالمبدأ، الذي هو التوصل إلى الفصل.\nوأما التمحيص فإزالة ما قد انفصل من الخير عن الشر.\nوكان المقصود به ما ذكره الله تعالى في قوله: ﴿لِيَمِيزَ ٱللَّهُ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِ﴾⟪8:37⟫.\n⟦3:937⟧\nإن قيل: على ماذا عطف قوله: ﴿وَلِيَبۡتَلِيَ ٱللَّهُ﴾⟪3:154⟫؟ ولم كرر الابتلاء بعد أن ذكره في قوله: (ليبتليكم؟ ولم علق الأول بالذات كلها، والثاني\nبما في الصدور؟ وما الفرق بين قوله: ما في الصدور، وبين قوله:\nما في القلوب، وخص ما في القلوب بالتمحيص؟\nقيل: أما ما عطف الابتلاء فعلى قوله: ﴿لِّكَيۡلَا تَحۡزَنُواْ﴾⟪3:153⟫، وفصل\nبينهما بما هو تسديد الكلام وإشباع للمعنى، وهذا جائز، وقد\nتقدم الكلام في نحوه، ويجوز أن يتعلق بمضمر دل عليه ما\nتقدم من قوله: ﴿ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ﴾⟪3:154⟫، وأما تكريره\nوتعليق الأول بالذات والثاني بما في الصدور، فإن لله تعالى\nتكليفين: الأحكام والمكارم كما تقدم، والأحكام قبل المكارم.\nوجلها متعلق بالضمائر، وعمل الجوارح فيها قليل، فحيث\n⟦3:938⟧\nما أراد منهم الحكم وهو الثبات في الحرب والجد بالجوارح، علق\nالابتلاء بالجملة، وحيث ما قصد المكارم من إصلاح الضمير.\nمن نقض الحزن ورفض الذعر ذكر الصدر، وحينما ذكر الإيمان\nالمحض ذكر القلب، وكل موضع يذكر الله في القرآن العقل.\nوالإيمان، فإنه يخص ذكر القلب، وإذا أراد ذلك وسائر\nالفضائل والرذائل ذكر الصدور، وهذا إذا اعتبر بالاستقراء\nانكشف، نحو قوله: ﴿وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ﴾⟪49:14⟫.\nوقوله: ﴿فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ﴾⟪22:32⟫، وقوله: ﴿أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ﴾⟪61:5⟫.\nوقوله: ﴿بَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ﴾⟪29:49⟫.\nوقوله: ﴿أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ﴾⟪39:22⟫.\nوقوله: ﴿فِي صُدُورِ ٱلنَّاسِ﴾⟪114:5⟫، ولما كان التمحيص أخص من الابتلاء\nكما تقدم خصه بالقلب، وهذه الأحوال الثلاث يترتب بعضها\nعلى بعض، فبإصلاح العمل يتوصل إلى إصلاح ما في الصدور\n⟦3:939⟧\nمن الشهوة والغضب، وبهما وبإصلاح ذلك يتوصل إلى إصلاح ما\nفي القلوب من الاعتبارات التي لا يعتريها شك وريب، وذلك\nما يبلغه العبد، وبه يستحق اسم الخلافة لله المذكور في قوله:\n﴿وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ﴾⟪7:129⟫، ثم قال: ﴿وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ﴾⟪3:154⟫، أي عالم بجميع ما ينطوي عليه من الضمائر الطيبة والخبيثة.\nوخص الصدور دون القلب إذ هي أعم."}, {"a": [155], "v": 3, "p": 939, "ev": 3, "ep": 941, "sid": 1140, "t": "قوله تعالى: (إن الذين تولوا منكم يوم التقى الجمعان إنما استزلهم الشيطان ببعض ما كسبوا ولقد عفا الله عنهم إن الله غفور حليم (155)\n⟦3:940⟧\nقال السدي: هو خاص في الذين انهزموا إلى المدينة.\nوقال عمر وبه قال الربيع وقتادة: بل في الذين ولوا المشركين أدبارهم.\nفيكون عاما فيمن أبعد ومن لم يبعد، وبين أن الشيطان استزلهم\nبخطيئة كانت منهم.\nقال الزجاج: إنما أذكرهم خطايا سلفت لهم.\nفكرهوا أن يقتلوا قبل أن يتوبوا.\nوقيل: بل كان منهم خطيئة صارت مسهلة لسبيل الشيطان إليهم.\nفإن الإنسان إذا حصن ثغره بالعمل الصالح والعلم فقد سد طريق الشيطان على\n⟦3:941⟧\nنفسه، ومتى أهمل ثغره سهل سبيل عدوه إليه، وجعل له ثلمة\nيدخل منها عليه، وذلك بأن يفسد إرادته، وبين أنه تعالى عفا\nعنهم، وقيل: ذلك بحلمه عن تعجيل عقوبتهم.\nوقيل: بل بالغفران عنهم عاجلا وآجلا، وهو الصحيح، لأنه جعل\nعلة عفوه الأمرين، فقال: ﴿إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ﴾⟪3:155⟫."}, {"a": [156], "v": 3, "p": 941, "ev": 3, "ep": 945, "sid": 1142, "t": "قوله تعالى: (يا أيها الذين آمنوا لا تكونوا كالذين كفروا وقالوا لإخوانهم إذا ضربوا في الأرض أو كانوا غزى لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسرة في قلوبهم والله يحيي ويميت والله بما تعملون بصير (156).\n41)\n51)\nثلمة: الملمة با لضم \": فرجة المكسور والمهدوم. القاموس ص (1452).\nلصحفت في الأصل إلى (بحمله) والصواب ما أثبته.\nذكره ابن عطية عن ابن جريج. انظر: المحرر الوجيز (3 274).\nواختاره السمرقندي في بحر العلوم (1 310).\nقال أبو حيان: \"ألجمهور على أن معنى العفو هنا هو حط التبعات في\nالدنيا والاخرة 00. (إ ت أفه غفور زصير) أي غفور الذنوب.\nحليم لا يعاجل بالعقوبة، وجاءت هذه الجملة كالتعليل لعفوه تعالى عن\nهؤلاء الذين تولوا يوم أحد. . . \" البحر المحيط (3 99) وانظر: جامع\nالبيان (7 327)، والمحرر الوجيز (3 274)، وتفسير القرآن العظيم\nلابن كثير (1 395).\nسورة آل عمران، الإية: 156. ونصها: (يايخا الذينءامنوا لا ت) ولؤا\n؟ لذين كفروأ وفالوأ لإخونهتم اذاضربرا فى ا لازضى أؤ كالؤا غز ى) ؤكالؤأغدنا\nما مالؤاوماقتلوأ ل) خحل المه ذلك حمتحر لى قلوبهتم والئه قيءليمميث وألله سا\nلغملون بصير).\n941\n⟦3:942⟧\nالذين كفروا عام، وإن كان قد قال السدي:\nعني به عبد الله بن أبي وأصحابه.\nوالضرب في الأرض: الإبعاد في السفر.\nوغزى: جمع غاز، نحو شهد وقول في شاهد وقائل.\nوإخوانهم: من سلك طريقهم في الكفر والنفاق،\n⟦3:943⟧\nوالحسرة: الغم على ما فات، وأصلها الإعياء عن إدراك المطلوب.\nوسمي الغم بذلك: إذ لا يفيد الإعياء، وعلى هذا قيل:\n. . . إن ليتا وإن لوا عناء\nإن قيل: إذا كان الإخوان هم المقول لهم، فالوجه أن يقال:\nلو كنتم، لأنه يقال: قلت لزيد: لو فعلت كذا، ولا تقول فعل وأنت\nتعنيه، قيل معناه: قال بعضهم لبعض لأجل إخوانهم، أو\nيعني قالوا لبعض إخوانهم إذا ضرب بعضهم في الأرض لو كان\nالضاربون في الأرض عندنا. وتقدير الكلام: إذا ضربوا في\nالأرض فماتوا أو كانوا غزى فقتلوا: لو ظلوا عندنا لما حدث\n⟦3:944⟧\nذلك بهم، وبين الله تعالى أن ذلك لا يثمر لهم إلا حسرة في\nقلوبهم مع العلم بأن الله هو المحيي والمميت، وعلى نحوه قال\nأبو ذؤيب:\nيقولون لي لوكان بالرمل لم يمت. . . نشيبة والطر أو يكذب قيلها\nولو أنني استودعته الشمس لارتقت. . . إليه المنايا عينها أو رسولها\nإن قيل: لم قال: ﴿وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ﴾⟪3:156⟫ ولو علق ذلك\nبالسماع لكان أليق، لأن ما كان منهم قول مسموع لا فعل مرئي؟\nقيل: لما كان قول الكافرين ذلك قصدا منهم إلى عمل يجادلونهم\nخص البصر، كقولك لن يقول شيئا وهو يقصد به فعلا يحاوله:\nأنا أرى ما يفعله، إن قيل: إذا للمستقبل، وقد جعل ظرفا\nلقوله قالوا، ولا يجوز أن يقول: جئتك إذا زرتني، فما وجه ذلك؟\nقيل: إذا متى لم يقصد به وقت معين، كان متضمنا للشرط.\nفيكون الفعل الذي هو في تقدير جوابه بمعنى\n⟦3:945⟧\nالاستقبال، وكأنه قيل: إن ضربتم في الأرض، أو كلما ضربتم\nقالوا، واللام: (ليجعل الله) لام العاقبة."}, {"a": [157, 158], "v": 3, "p": 945, "ev": 3, "ep": 947, "sid": 1146, "t": "قوله تعالى: (ولئن قتلتم في سبيل الله أو متم لمغفرة من الله ورحمة خير مما يجمعون (157).\nيقال: مت ومت، والضم أقيس، والكسر كثير، والآيتان\n⟦3:946⟧\nتضمنتا إلزاما هو جار مجرى قياسين شرطيين اقتضيا الحرص\n⟦3:947⟧\nعلى القتل في سبيل الله، وبيانه ما أقول: إن قتلتم في سبيل الله أو\nمتم فيه حصلت لكم المغفرة والرحمة تنبيها أنه أوجبهما للثواب.\nولما عنى في الثانية الموت المطلق والقتل العارض قدم أبينهما\nعندهم إذ لابد منه، فكأنه قيل: إن حصل ما لابد منه بوجه وهو\nالموت حتف الأنف، أو ما هو عارض، وعندكم أنه قد يكون\nمنه خلاص، وهو القتل، فالحشر لا محالة حاصل."}, {"a": [159], "v": 3, "p": 947, "ev": 3, "ep": 955, "sid": 1148, "t": "قوله تعالى: (فبما رحمة من الله لنت لهم ولو كنت فظا غليظ القلب لانفضوا من حولك فاعف عنهم واستغفر لهم وشاورهم في الأمر فإذا عزمت فتوكل على الله إن الله يحب المتوكلين (159).\n⟦3:948⟧\nقال النحولون (ما) زائدة، وعلى هذا ﴿عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ﴾⟪23:40⟫.\nوقوله: ﴿فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ﴾، وأفاد التأكيد.\nووجه تأكيده أنه نكرة تدل على إبهام ما علق به، وإبهامه يقتضي التعجب.\nفكأنه بعظيم من رحمته (لنت لهم) واللين عبارة عن حسن الخلق.\nوحسن الكلام بالصفو والزلال، حتى قال الشاعر:\n⟦3:949⟧\n. فتى مثل صفو الماء ليس بباخل.\nاستعمل في ضده الفظاظة.\nوغلظ القلب: عبارة عن قلة الرحمة. وبإزائه رقة القلب.\nوالانفضاض: التفرق، وانفض وارفض يتقاربان إلا أن انفض اعتبارا بانكسار بعضهم عن بعض، وارفض اعتبارا برفض بعضهم بعضا.\nوالمشاورة: استخراج صائب الرأي عن الغير.\nواششقاقه من شور العسل، وشرت الدابة وشورتها،\n⟦3:950⟧\nوالعزم: ثبات الرأي على الأمر، نحو إجماع الرأي، والتوكل\nعلى الله الثقة به والوقوف حيثما وقف، وبين أدنى منزلة له\nنحو ما قاله للأعرابي \"اعقله وتوكل\" وبين غايته التي هي\nكحال إبراهيم عليه السلام بون بعيد.\nونبه بقوله: ﴿فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ﴾⟪3:159⟫\nعلى فعمته على النبي - صلى الله عليه وسلم - أولا وعلى أمته ثانيا.\nكقوله: ﴿لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ﴾⟪9:128⟫ الآية.\nوقوله: ﴿وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ﴾⟪21:107⟫ وأمره بالعفو عن\nتقصيرهم فيما يلزمهم له، وأن يستغفر لهم من ذلك، كقوله:\n⟦3:951⟧\n﴿وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ﴾⟪9:103⟫\nثم أمره بإجراء نفسه مجرى أحدهم في الرأي الذي هو خاص بالإنسان.\nثم قال: ﴿فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ﴾⟪3:159⟫ أي وإن قاربتم هذه المقاربة فليكن اعتمادك على الله، وتقويتك به، كما قال النبي - صلى الله عليه وسلم -: \"من سره أن يكون أقوى الناس فليتوكل على الله\".\nواختلف في مشاورة النبي لأصحابه على أي وجه، فقال سفيان بن عيينة: ليقتدي به غيره، وقال قتادة: تطييبا لقلوبهم، ويجب أن نقدم مقدمة\nتبين في أي أمر أولا تدخل الاستشارة؟ ثم من استشار غيره فلأي\n⟦3:952⟧\nقصد يستشير؟ فيقال: أما ما يستشار فيه فهو الأمور الممكنات\nالمتعلقة باختيار الفاعل، وأما القصد بالاستشارة فتارة لاستضاءة\nالمستشير برأي المستشار، أو لئلا يلام إذا استبد بالأمر، فيتفق\nوقوعه بخلاف المراد، ولهذا قيل: الاستشارة حصن من الندامة.\nوأمن من الملامة، وتارة طلبا لهداية المستشار، إما لأن يتبين له\nخطأ رأيه إن كان له رأي خطأ في ذلك الأمر، وإما أن لا يعتقد هو\nأو غيره أن الاستبداد فضيلة فيستبد برأيه فيما ربما يؤذي إلى\nفساد: إما لإكرامه أو تعظيمه، فإذا تقرر هذا فأمور النبي - صلى الله عليه وسلم - لا تنفك: إما أن تكون شيئا دينيا أو دنيويا.\nفإن كان دينيا فمعلوم أن النبي - صلى الله عليه وسلم - غير محتاج إلى الاستضاءة برأي غيره من البشر، لما أمده الله تعالى به من النور الإلهي، وما كان يستشيرهم في أصول الشريعة، لكن ربما كان يستشيرهم في شيء من فروعها، التي هي من مسائل الاجتهاد لنا، نحو ما روي أن النبي - صلى الله عليه وسلم - استشار\n⟦3:953⟧\nإصحابه في شعار يرفع للصلاة، ومثل ذلك تشريف لهم أولا.\nوتنبيه أن ما سبيله الاجتهاد فحقه الاستعانة فيه بالآراء الكثيرة\nالصحيحة، لينقدح منها الصواب، وأما ما كان من الأمور\nالدنيوية كالمساحة والكتابة والحساب، فمعلوم أنه كان مستغنيا\nبغيره في كثير منها، بل قد صرح في ذلك بقصوره (1) فيما روي أنه\n⟦3:954⟧\nعليه السلام لما ورد المدينة ووجد أهلها يؤبرون (1) نخلهم، فقال:\n\"ما أرى أن ذلك ينفع \" فتركوه، فتبين ذلك في نقص أثمارهم\nفشاوروه فقال: \"أنتم أعلم بأمور دنياكم، وأنا أعلم بأمور\nآخرتكم\" (2).\nوعلى هذا. ما كان يتعلق بأمور الحرب المتعلقة\nبتهييجها تارة وتسكينها تارة، وبالمن فيها تارة وبالافتداء تارة.\nولذلك لما هم بمصالحة عيينة بن حصن على ثلث ثمار المدينة.\nقال بعضهم: أبوحي هذا أم برأي رأيته؟ قال: \"برأي رأيته\"\nفراجعوه وبينوا له موضع الصواب، وترك رأيه لرأيهم.\n⟦3:955⟧\nوكذا مراجعة عمر له بما هم به من كتاب القضية عام الحديبية.\nفثبت أن ما يتعلق بالأمور الدنيوية حال الرسول عليه السلام\nوغيره فيه سواء، والمشاورة مستحبة له كما هي مستحبة لغيره."}, {"a": [160], "v": 3, "p": 955, "ev": 3, "ep": 960, "sid": 1156, "t": "قوله تعالى: (إن ينصركم الله فلا غالب لكم وإن يخذلكم فمن ذا الذي ينصركم من بعده وعلى الله فليتوكل المؤمنون (160)\nأكثر المفسرين جعلوا نصرة الله للعبد في الحقيقة تقويته بأعظم السلطانين\nالذي هو الحجة القاهرة وأعظم التمكينين الذي هو العاقبة المذكورة\nفي قوله: ﴿وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ﴾ وفي أشرف الدارين\n⟦3:956⟧\nحيث لا ينفع مال ولا بنون. فقالوا: معناه: إن حصل لكم النصرة فلا تعتدوا ما يعرض من العوارض الدنيوية في بعض الأحوال غلبة، وإن\nخذلكم في ذلك فلا تعتدوا ما يحصل لكم من القهر في الدنيا\nنصرة، فالنصرة والخذلان معتبران بالمآل.\nومنهم من اعتبر ذلك في أمر الدنيا، فقال: معناه: إن نصركم الله في الدنيا بموافقتكم - صلى الله عليه وسلم - فلا غالب لكم، وإن لم ينصركم فلا ناصر لكم.\nوحمله على الأول يدخل فيه الثاني، فإن من نصر في آخرته فهو في\nالدنيا منصور، وإن لم يدرك نصرته إلا بالبصيرة دون البصر، وحمله\nعلى الثاني قد ينفك من نصرة الآخرة.\nوقوله. ﴿وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ﴾⟪3:160⟫ أمرهم بالتوكل عليه، كما أمر النبي - صلى الله عليه وسلم - في الآية الأولى، وأن يستجلبوا النصرة منه بذلك.\n⟦3:957⟧\nقو له تعالى: (وما كان لنبي أن يغل ومن يغلل يأت بما غل يوم القيامة ثم توفى كل نفس ما كسبت وهم لا يظلمون (161)\nالغلول: تناول مال الغير بضرب من المكيدة، وكثر استعماله\nفي الغنيمة، وسبب نزول ذلك، قال ابن عباس: هو أن فقد\nقطيفة حمراء يوم بدر، فقال بعض الناس: لعل النبي - صلى الله عليه وسلم - أخذها، وقال الضحاك: هو عتاب لمن استحفظوا الثنية\n⟦3:958⟧\nيوم أحد، حيث قال بعضهم: ربما يقول النبي - صلى الله عليه وسلم -: \"من تناول شيئا فهو له \" فنبقى بلا غنيمة، فعلى هذا يكون هذا القول ثناء\nعليه - صلى الله عليه وسلم -، وقال بعضهم: بل ذلك حث، للنبي على التعفف، وإن كان معلوما أنه لا يغل، كقوله: ﴿لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ﴾⟪39:65⟫.\nومن قرأ (يغل) فقد قيل: نهي للناس أن ينسبوا ذلك إلى النبي - صلى الله عليه وسلم -\n⟦3:959⟧\nمن قولهم: أغللت فلانا. كقولهم: أكذبته.\nوقرأ رجل بحضرة ابن عباس \"يغل\" فقال: بلى ويقتل.\nفكأنه حمله على الخبر، ولم يرتض قراءته.\nوقال الحسن: نهي أن يخونوه.\nفإن قيل: فلم خصه والخيانة معه ومع غيره مذمومة؟\nقيل: قد قال بعض الناس: إن تخصيصه تعظيم له.\nفإن الخيانة وإن كانت مستقبحة مع كل أحد.\nفمع من يرشح لهداية الناس أقبح،\n⟦3:960⟧\nوقال بعض الناس: إن ذلك في الحقيقة نهي عن الخيانة رأسا في\nكل ما أتى به النبي - صلى الله عليه وسلم - من الأحكام، كقوله: ﴿لَا تَخُونُواْ ٱللَّهَ وَٱلرَّسُولَ﴾⟪8:27⟫.\nوقال بعض الناس: قراءة من قرأ؟ (يغل) أولى، لأن كل ما جاء في التنزيل من هذا النحو فمسند إلى الفاعل دون المفعول.\nنحو ﴿وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ﴾⟪3:145⟫.\nوقوله: ﴿وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ﴾⟪3:179⟫."}, {"a": [161], "v": 3, "p": 960, "ev": 3, "ep": 961, "sid": 1161, "t": "وقوله: ﴿وَمَن يَغۡلُلۡ﴾⟪3:161⟫ تعظيم للغلول، وأنه لا انفكاك له من جزائه، فكأن ما قد غله يصحبه، وعلى هذا ما قال النبي - صلى الله عليه وسلم -:\n\"لا أعرفن رجلا يأتي بفرس له حمحمة\").\nوعلى هذا ما قاله - صلى الله عليه وسلم -:\n\"لا أعرفن رجلا يأتي ببعير قد غله له رغاء\".\n⟦3:961⟧\n، وعلى هذا ما حكي عن لقمان: ﴿يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٖ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ﴾⟪31:16⟫ وقد تقدم الكلام في باقي الآية."}, {"a": [162], "v": 3, "p": 961, "ev": 3, "ep": 963, "sid": 1162, "t": "قوله تعالى: (أفمن اتبع رضوان الله كمن باء بسخط من الله ومأواه جهنم وبئس المصير (162)\n⟦3:962⟧\nقرئ: رضوان، وهما مصدران نحو: كفران وحسبان.\nوهو غاية الرضا، و (باء) بكذا رجع به، ومنه البواء في القصاص.\nإذا كان فيه مرجوع فيمن قتل.\nوالسخط: حصول غضب يقتضي عقوبة.\nوإذا استعمل في الله فبمعنى إيجابه العقوبة.\n⟦3:963⟧\nوالغيظ يقاربه، إلا أنه يقال إذا كان معه تغير منكر، ولا يوصف به\nالله، والفرق بين المصير والمرجع: أن الرجوع هو انقلاب\nالشيء إلى حال كان عليها، أو ما هو مقدر تقديرها.\nوالمصير: التنفل من حال إلى حال أخرى، فهو أعم من الرجوع.\nوالقصد بالآية تبعيد ما بين الفريقين كقوله: ﴿لَا يَسۡتَوِيٓ أَصۡحَٰبُ ٱلنَّارِ وَأَصۡحَٰبُ ٱلۡجَنَّةِۚ﴾⟪59:20⟫."}, {"a": [163], "v": 3, "p": 963, "ev": 3, "ep": 966, "sid": 1164, "t": "قوله تعالى: (هم درجات عند الله والله بصير بما يعملون (163)\n⟦3:964⟧\nقيل: هي صفة ل ﴿أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ﴾⟪3:162⟫، وبين أنه كما أن من باء بسخط\nمن الله مأواه جهنم، فمن اتبع رضوانه هم ذوو درجات عند الله\nأي ثواب كبير، والصحيح أنه قسم الناس في الأولى قسمين: فائزا\nبرضوانه وبائيا بسخطه، وبين في هذه أن القسمين كل واحد بين\nالبعض والبعض تفاوتا، وذاك أن الناس إذا اعتبروا فمن بين\nملك مقرب، كما قال: ﴿إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ﴾⟪12:31⟫.\nوبين أخس بهيمة، كما قال: ﴿وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ﴾⟪5:60⟫.\nوما بينهما بحيث لا يمكننا حصره، ولذلك قيل في المثل:\n⟦3:965⟧\nالناس أخياف وشتى في الشيم وكلهم يجمعهم بيت الأدم\nولتفاوت درجاتهم وتفاوت ثوابهم وعقابهم ما روي أن\nالجنة درجات والنار دركات، ونبه بقوله: ﴿وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ﴾⟪3:163⟫، أنه لا يخفى عليه ما يتحراه كل واحد، فإذن\n⟦3:966⟧\nيقف كل موقفه الذي يستحقه."}, {"a": [164], "v": 3, "p": 966, "ev": 3, "ep": 968, "sid": 1167, "t": "قوله تعالى: (لقد من الله على المؤمنين إذ بعث فيهم رسولا من أنفسهم يتلو عليهم آياته ويزكيهم ويعلمهم الكتاب والحكمة وإن كانوا من قبل لفي ضلال مبين (164)\nالمنة: استكبار النعمة بالفعل أو بالقول، فأما بالفعل\nفحسن، وأما بالقول فما لم يكن فيه وعظ ممن له الوعظ\nفمستقبح، ولذلك قيل: المنة تهدم الصنيعة، وقوله:\n⟦3:967⟧\n﴿رَسُولٗا مِّنۡ أَنفُسِهِمۡ﴾⟪3:164⟫، وقوله: ﴿لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ﴾⟪9:128⟫\nقيل: عنى من أهل بيتهم ومن العرب.\nوقال بعضهم: ليس هذا بسائغ، إذ لم يخص أهل بيته به ولا العرب\nخاصة، بل هو مبعوث إلى العالمين، فالوجه في قوله: ﴿مِّنۡ أَنفُسِكُمۡ﴾\nأي من البشر، وذاك أن كل ما أوجده الله في هذا\nالعالم لا يأخذ نفعه إلا مما بينه وبين المأخوذ منه ملاءمة ما، وذلك\nحكم مستمر في كل شيء، فلما كان كذلك جعل الله تعالى الأنبياء\nالمبعوثين إلى كافة البشر بشرا مثلهم في الخلقة والصورة، وخصهم\nبفضل قوة التمييز والمعرفة، يأخذون من ملائكته وحيه.\nويولونهم، ولولا كونهم من جنسهم لما قدروا على أخذهم\n⟦3:968⟧\nمنهم، ولهذا قال: ﴿وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا﴾⟪6:9⟫، فبين\nتعالى نعمته عليهم أن رشح لهم من سهل تناولهم منه.\nوقوله: ﴿يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ﴾⟪3:164⟫ لم يعن تلاوة آيات القرآن فقط.\nبل عنى بذلك تنبيههم على آيات الله في السموات والأرض.\nوفي أنفسهم، ولهذا حسن عطف قوله: ﴿وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ﴾⟪3:164⟫\nعليه، وقد تقدم الفصل بين الكتاب والحكمة، ومعنى التزكية."}, {"a": [165], "v": 3, "p": 968, "ev": 3, "ep": 971, "sid": 1169, "t": "قوله تعالى: (أولما أصابتكم مصيبة قد أصبتم مثليها قلتم أنى هذا قل هو من عند أنفسكم إن الله على كل شيء قدير (165)\n⟦3:969⟧\nدخل ألف الاستفهام على واو العطف ليفيد مع الاستفهام\nتعلق ما بعده بما قبله، وكذلك إذا قلت: أو كان كما تقول؟ إذا\nأردت بناء كلامك على كلام المخاطب، وكان المسلمون قتلوا\nمن المشركين يوم بدر سبعين، وأسروا سبعين، فلما كان يوم\nأحد، وقتل جماعة من المسلمين تغير قلوب قوم، فخاطبهم الله\nبذلك، وعنى أنكم أنكرتم أن نالكم منهم شطر ما نالهم منكم.\nوأخذتم تقولون: آنى نالنا ذلك؟! فأجابهم الله بأن ذلك من عند\nأنفسكم، فإن الله وعدكم أن ينصركم بشريطة أن تصبروا وتتقوا،\n⟦3:970⟧\nفخالفتم، وقد قيل: مخالفتهم أنهم دعوا إلى التحصن بالمدينة\nفأبوا إلا الخروج، وقيل لاختيارهم الفداء يوم بدر.\nوقيل لمخالفة الرماة، والأولى أن يكون عاما في جميعها، وهو\n⟦3:971⟧\nإشارة إلى ما فضله قبل بقوله: ﴿حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ﴾⟪3:152⟫ الآية.\nإن قيل: ما وجه قوله: ﴿إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ﴾⟪3:165⟫ عقب هذه الآية؟\nقيل: نبه بذلك أن لم يصبكم ما أصابكم لوهن في دينكم أو ضعف في قدرة الله، فكأنه قيل: هو من عند أنفسكم، لا من خلل دخل في أمره، فإن الله على كل شيء قدير، ومن كان هذه حاله فهو قادرعلى دفاعهم."}, {"a": [166, 167], "v": 3, "p": 971, "ev": 3, "ep": 977, "sid": 1172, "t": "قوله تعالى: (وما أصابكم يوم التقى الجمعان فبإذن الله وليعلم المؤمنين (166)\nدخول الفاء في قوله: ﴿فَبِإِذۡنِ ٱللَّهِ﴾⟪3:166⟫ لتضمن الذي معنى\nالشرط، كأنه قيل: إن أصابتكم مصيبة فإصابتها بإذن الله،\n⟦3:972⟧\nوقد أصابتكم، فإذا كان بإذن الله، وأصل الإذن العلم بالشيء\nمن أذنت له، أي استمعت إليه فعلمته، ثم يقال في التعارف\nلمن لا يمنع من فعل شيء مع العلم به، والقدرة عليه على منعه.\nسواء أمر به أو لم يأمر: فعل كذا بإذنه، فإذا حمل على العلم\nفنحو قوله: ﴿وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا﴾⟪6:59⟫ وإذا حمل\nعلى الأمر فليس يعني أنه أمر الكفار بذلك، وإنما عنى أنه أمر\nالملائكة المذكورين في قوله: ﴿فَٱلۡمُدَبِّرَٰتِ أَمۡرٗا﴾⟪79:5⟫.\n⟦3:973⟧\nإن قيل: وإذا حمل على الأمر فليس يعني العلم.\nفكيف يصح وقد قال بعده: (وليعلم المؤمنين)؟\nقيل: ليعلم المؤمنين أي ليحصل إيمان المؤمنين، وقد تقدم حقيقة ذلك.\nثم بين تعالى ما كان من ذنوبهم، فقال: ﴿وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ﴾⟪3:167⟫ أي استعملوا النفاق في أعمالهم.\nولما قيل لهم إما أن تحاربوا أو تحضروا مكثرين للسواد دافعين عن\nالحوزة، قالوا مجيبين بما حكي عنهم، وقول السدي: ادفعوا\nبتكثير سوادنا إن لم تقاتلوا، وقول غيره: رابطوا\n⟦3:974⟧\nبالقيام على الجبل إن لم تقاتلوا، وقول غيرهما: احضروا موضع\nالحرب. ليست بأقوال مختلفة في المعنى، كما قدره بعض\nالنقلة، وإلا ذلك اختلاف عبارات وتعيين أمثلة لمقصد واحد.\nوحمل بعض الصوفية ذلك على الجهاد فيقول: معناه إما أن تبلغوا\nمنازل الصديقين في مجاهدة وإماتة الشهوات أو ادفعوها عن\n⟦3:975⟧\nارتكاب المحارم، وزفوها عن احتقاب الماثم إلط لم تقدروا على\nالأول، ثم عيرهم بقولهم: ﴿لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ﴾⟪3:167⟫، أي لو\nصادفنا من أنفسنا منكرا لارتسمنا ما رسمتم، تنبيها أنه خفي عليهم\nعيوب أنفسهم، وقوله: ﴿هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ﴾⟪3:167⟫ تنبيه على نفاقهم؛ وذاك أن المنافق كأنه بين الكافر والمؤمن، فإنه من حيث ما يظهر الشهادتين، ويلتزم ظواهر الشريعة بالقول، وظواهر الأعمال محكوم له بالإيمان، ومن حيث يتحرى في اعتقاده تحري الكفار كافر، وبين أحوال المنافقين تفاوت، بين تعالى بهذا القول أنهم في هذا القول بالكفار أشبه منهم بالمسلمين،\n⟦3:976⟧\nوأقرب: قيل: هو من القرب وقيل: من القرب من الماء.\nثم بين تعالى علة قربهم من الكفر، فقال: ﴿يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ﴾⟪3:167⟫، تنبيها أن الاعتبار في الإيمان المستحق به الثواب\nبالنيات والضمائر، لا بالأقوال المجردة عن الاعتقاد، ولهذا شهد\nللمنافقين في قولهم: ﴿نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ﴾⟪63:1⟫ بالكذب، فقال:\n﴿وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ﴾⟪63:1⟫، وحكم لمن تلفظ\nبالكفر من غير مطابقة الاعتقاد له بالإيمان، فقال: ﴿إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ﴾⟪16:106⟫، ثم حذرهم عن اعتقاد غير الحق بقوله: ﴿وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ﴾⟪3:167⟫،\n⟦3:977⟧\nكقوله: ﴿أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ﴾⟪2:235⟫.\nوقوله تعالى: ﴿يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى﴾⟪20:7⟫ وقوله: ﴿يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ﴾⟪40:19⟫.\nوهذه الآية كالشرح لما أجمله في الأولى، حيث قال: ﴿قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ﴾⟪3:165⟫."}, {"a": [168], "v": 3, "p": 977, "ev": 3, "ep": 978, "sid": 1178, "t": "قوله تعالى: (الذين قالوا لإخوانهم وقعدوا لو أطاعونا ما قتلوا قل فادرءوا عن أنفسكم الموت إن كنتم صادقين (168)\nهذه الآية من تمام صفة المنافقين عبد الله بن أبي وأصحابه.\nقالوا: إن قتلى أحد لو أطاعونا في التأخر عن القتال ولزموا\nبيوتهم ما قتلوا، وإعراب (الذين): إما نصب على البدل من\n(الذين نافقوا)، أو رفع على خبر الابتداء المضمر، أو بدل من\nالضمير في (يكتمون).\nإن قيل: لم أخر ذكر القعود عن القول\n⟦3:978⟧\nالذين قالوا لإخوانهم وقعدوا لو أطاعونا ما قتلوا قل فادرءوا عن أنفسكم الموت إن كنتم صادقين (168)\nمع كونه مقدما في المعنى؟ قيل: إن قوله: (وقعدوا) في تقدير\nالحال، أي قالوا وهم قاعدون، كقولك:، خرج زيد وقد ركب.\nويكون ركوبه قبل الخروج، وقد أكذبهم الله في ذلك بقو له: ﴿قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ﴾⟪3:168⟫ وكأنه قال: القتل ضرب من\nالموت، فإن كان لكم سبيل إلى دفعه عن أنفسكم بفعل اختياري\nفادفعوا عنها الموت، وإذ لم يمكنكم ذلك دل أنكم مبطلون قي\nدعواكم."}, {"a": [169, 170], "v": 3, "p": 978, "ev": 3, "ep": 985, "sid": 1179, "t": "قوله تعالى: (ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء عند ربهم يرزقون (169)\n⟦3:979⟧\nروي عن ابن عباس والحسن أن النبي - صلى الله عليه وسلم - قال:\n\"لما أصيب إخوانكم بأحد جعل الله أرواحهم في أجواف طير خضر ترد أنهار\nالجنة، وتأكل من أثمارها، وتأوي إلى قناديل معلقة في ظل العرش.\nفلما وجدوا طيب مأكلهم ومشربهم ومقيلهم قالوا: من يبلغ إخواننا\nعنا: أنا أحياء في الجنة، نرزق، كي لا ينكلوا عن الحرب ؟ فقال\nتعالى: أنا أبلغهم عنكم، فأنزل هذه الآية\".\nفدل ذلك أن الأرواح أحياء تثاب وتعاقب قبل أن تعاد إلى الأجسام يوم القيامة، وعلى هذا قال في صفة آل فرعون: ﴿ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ﴾⟪40:46⟫، ودل عطف قوله: ﴿وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ﴾⟪40:46⟫\n⟦3:980⟧\nأن عرضهم على النار قبل يوم القيامة.\nوروي: \"إن أحدكم إذا مات عرض عليه مقعده بكرة وعشية.\nفيقال: هذا مقعدك حتى تبعث إليه \".\nوهذا قول السلف وأصحاب الحقائق، الذين عرفوا حقيقة الروح المعنية هاهنا، وكونه جوهرا.\n⟦3:981⟧\nله بذاته قوام، وأما متأخرو المعتزلة الذين لم يتجاوزوا منزلي\nالحس والوهم، ولم يروا الروح إلا ريحا أو عرضا، فبعضهم\n⟦3:982⟧\nقال: يعني أحياء يوم القيامة، ووصفهم بذلك في الحال لقرب\nالقيامة عند الله، كقوله: ﴿أَتَىٰٓ أَمۡرُ ٱللَّهِ﴾⟪16:1⟫، ومعنى (عند ربهم)\nأي في علم الله، وبعضهم قال: أحياء بالذكر، وبعضهم قال:\nأحياء بالإيمان، وإرادة هذه المعاني بالآية غير ممتنعة، فإن\nالمؤمنين أحياء بكل ذلك، كما قالوا، ولكنهم مع ذلك أحياء\nبالأرواح على ما ورد به الخبر، وزعمهم أن ما ورد من الأخبار\nفي أرواح الشهداء ليس بصحيح، فإن العقل لا يقتضي ذلك.\nفهم إن عنوا العقول الصدئة التي عناها من قال:\n⟦3:983⟧\nفلان لم يؤت من العقل إلا مقدار ما يلزم به حجة الله فقد صدقوا، وإن\nعنوا العقول المجلوة السليمة من درن الهوى المعنية بقوله: ﴿إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ﴾⟪50:37⟫.\nوبقوله: ﴿إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ﴾⟪39:21⟫ فليس كما ظنوا.\nومن زعم أن القول بحياة الأرواح يؤدي إلى القول بالرجعة\nفوهم فاسد، ولئن كان ذلك يؤدي إلى ما قالوه فإحياء الله من\nوصفهم بقوله: ﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ﴾⟪2:243⟫ الآية.\n⟦3:984⟧\nوإحياء عيسى الأموات أكثر تأدية إليه، وأما على طريقة\nالمتصوفة المذكورة في قوله: ﴿قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ أَوِ ٱدۡفَعُواْۖ﴾⟪3:167⟫\nفإنهم قالوا: لما كان الإنسان مركبا من بدن وروح، والعقل تابع للروح.\nوالهوى تابع للبدن، وبتوهين أحدهما تقوية الآخر، نبه تعالى أن\nمن جاهد نفسه، وقتل هواه في سبيل الله فلا تحسبنه ميتا، وعلى\nهذا قيل: قتل النفس في الدنيا حياة الآخرة.\nإن قيل: لم وصفهم بالفرح، وقد قال تعالى: ﴿إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ﴾⟪28:76⟫؟ قيل: الفرح تجاوز الحد في السرور بالملاذ، ولما كانت\n⟦3:985⟧\nالملاذ الدنيوية غير متنافس فيها ذم الفرحين بها، ولما كانت\nالملاذ الأخروية متنافسا فيها، كما قال: ﴿وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ﴾⟪83:26⟫ أباح لهم الفرح بها، حتى قال: ﴿فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ﴾⟪10:58⟫.\nوأما استبشارهم بالذين لم يلحقوا بهم، فتنبيه أنهم يعرفون نعمة\nالله بالموت والقتل في سبيله، ويسرون إذا أخبروا بقتل أو موت\nإخوانهم بخلاف أبناء الدنيا، وقوله: ﴿أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪3:170⟫ متضمن لذكر كل شيء يكدر الحياة، فإن ما يعرض\nفي الدنيا: إما خوف لوقوع محذور، أو حزن لفوت محبوب.\nوالضمير في: (عليهم) يجوز أن يكون ضميرا للذين لم يلحقوا بهم، وأن\nيكون للمستبشرين، وأن يكون لهما.\nإن قيل: لم رفع (أحياء) ونصب (فرحين)؟\nقيل: لأن (فرحين) حال للذين قتلوا، والنصب به أولى، و (أحياء) استئناف، ولو نصب لكان معناه: بل احسبهم أحياء، ولم يرد ذلك، وإنما أراد بت الحكم بكونهم أحياء."}, {"a": [171, 172], "v": 3, "p": 986, "ev": 3, "ep": 988, "sid": 1187, "t": "قوله تعالى: (يستبشرون بنعمة من الله وفضل وأن الله لا يضيع أجر المؤمنين (171)\nإن قيل: ما الفرق بين النعمة والفضل هاهنا؟\nقيل: الإشارة بهما إلى المذكورين في قوله: ﴿لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ﴾⟪10:26⟫، فالنعمة هي الحسنى والفضل هاهنا الزيادة.\nإن قيل: لم نكرهما؟\nقيل: التنكير في مثله على وجهين:\nأحدهما: ليدل على بعض غير معين.\nوالثاني: قصد إلى إبهام المراد تعظيما لأمره، وتنبيها أنه\n⟦3:987⟧\nيصعب إدراك شرحه، وكأن التنكير في هذا إشارة إلى نحو ما\nقال: \"فيها ما لا عين رأت، ولا أذن سمعت \"\nإن قيل: ما حقيقة ﴿لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ﴾⟪3:171⟫؟\nقيل: لما كان من الأعمال التي صورتها في الدنيا صورة العبادات التي يستحق بها الثواب ما هو في الحقيقة غير عبادة يستحق بها الأجر.\nوإياها قصد بقوله: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫\nبين هاهنا أن عمل المؤمنين لا يجري مجرى أعمال هؤلاء.\nإن قيل: ما الفرق بين الإفضال والإحسان؟\nقيل: كلاهما اسم الزيادة على فعل العدالة.\nوتجاوز ما يجب إلى ما يستحب، لكن الإحسان يقال\nباعتبار جمال الفعل في نفسه وتحري تحسينه، والإفضال يقال\nباعتبار فعل بفعل أو فاعل، فيقال للزائد على الإجزاء فاضل.\n⟦3:988⟧\nفالاستجابة لله وللرسول، وإن جمع بينهما في\nالإيجاب فالواجب بالقصد الأول استجابة الله، لكن لما لم تتم\nاستجابته إلا باستجابة رسوله صار ذلك واجبا، لأن ما لا يتم\nالواجب إلا به فهو واجب، والاستجابتان مختلفتان، فإن استجابة\nالله بتوجيده وعبادته، واستجابة رسوله بتلقي الرسالة عنه وقبول\nالنصح منه."}, {"a": [173], "v": 3, "p": 988, "ev": 3, "ep": 991, "sid": 1189, "t": "قوله تعالى: (الذين قال لهم الناس إن الناس قد جمعوا لكم فاخشوهم فزادهم إيمانا وقالوا حسبنا الله ونعم الوكيل (173)\n⟦3:989⟧\nقيل: سبب نزول ذلك أن أبا سفيان وأصحابه تقدموا إلى نعيم\nابن مسعود ورضخوا له شيئا، وقالوا: إذا مررت بمحمد\nوأصحابه، فقل: إنا قد أجمعنا على قصدهم بخيل لا قبل لهم بها.\nفلما أتاهم، وقال لهم ذلك، قالوا: حسبنا الله ونعم الوكيل.\nإن قيل: لم: ﴿قَالَ لَهُمُ ٱلنَّاسُ﴾⟪3:173⟫ وإنما قال ذلك رجل واحد؟\nقيل: لما كان القائل لنعيم أبا سفيان وأصحابه المعبر عنهم بقوله: ﴿إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ﴾⟪3:173⟫ سمي المنبئ عنهم بذلك (الناس)، تنبيها\nأن المخوفين في الحقيقة هم المخوف منهم، والآية وإن نزلت فيهم\n⟦3:990⟧\nفالمعني بها هم ومن جرى مجراهم، ونبه بما حكى من جوابهم\nوفعلهم على نهاية ما يطلب من إيمان العبد وتوكله لما أظهروا\nقولا وفعلا، وبين أنهم عادوا بنعمة وفضل في دنياهم وأخراهم\nفي أن لا خوف عليهم ولا هم يحزنون، لا أنهم لا يعرض لهم في\nالدنيا ما يحزن ويخوف من سوء، ولكن لا يؤثر فيهم، والمقصود\nبهذه النعمة والفضل أعظم مما قال بعض المفسرين من أن المسلمين\nلما حضروا بدرا الصغرى، ولم يحضروا للموعد صادفوا بها سوقا،\n⟦3:991⟧\nفاشتروا ما ربحوا فيه، فكان ذلك هو الفضل والنعمة، فإن\nأرباح التجارة الدنيوية أدون من أن يكون مقتصرا عليها في مقابلة\nالمتوكلين على الله، الراضين عن الله تعالى، المرضي عنهم."}, {"a": [174], "v": 3, "p": 991, "ev": 3, "ep": 992, "sid": 1192, "t": "وقوله ﴿رِضۡوَٰنَ ٱللَّهِۗ﴾⟪3:174⟫ يجوز من حيث تقدير الكلام: أن يكون على معنى،\n⟦3:992⟧\nأن رضي الله عنهم، وأن يكون على أن رضوا عن الله، فإن من رضي\nعن الله فقد رضي الله عنه، ولهذا قال تعالى: ﴿رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ﴾ وذكر تعالى في الآيات الثلاث ثلاث فرق، بعضهم أخص من\nبعض، وذاك أن المؤمنين المستجيبين لله عام، والذين أحسنوا واتقوا\nأخص،، فجعل تعالى للمستجيب لله أجرا غير معين، وللمحسن\nالمتقي في ذلك أجرا عظيما، وهذا شبيه بما تقدم في قوله ﴿وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ﴾⟪3:136⟫ ﴿وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾."}, {"a": [175], "v": 3, "p": 992, "ev": 3, "ep": 996, "sid": 1193, "t": "قوله تعالى: (إنما ذلكم الشيطان يخوف أولياءه فلا تخافوهم وخافون إن كنتم مؤمنين (175)\nإن قيل: إلى ماذا أشار بقوله: (ذلكم)؟\nقيل: فيه أقوال:\nالأول: أنه إشارة إلى من قال: ﴿إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ﴾⟪3:173⟫\n⟦3:993⟧\nفسماه شيطانا لمشابهته في فعله، والثاني: أنه إشارة إلى الشيطان\nالمتعارف بين الناس، أي الشيطان الذي عرفتموه هو الذي يخوف.\nوالثالث: إشارة إلى ما دل عليه قوله: ﴿وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ﴾⟪3:139⟫.\nأي ذلك العارض الذي هو الوهن والحزن شيطان: كقول الشاعر:\nما ليلة الفقير إلا شيطان. . .\n⟦3:994⟧\nوأما (أولياءه) فقد قال ابن عباس: معناه: يخوفكم\nأولياءه، فعلى هذا حذف المفعول الأول، كقوله: ﴿لِّيُنذِرَ بَأۡسٗا شَدِيدٗا﴾⟪18:2⟫ ووقولهم: فلان يعطي الدراهم، فالأولياء على هذا هم المخوف بهم،\n⟦3:995⟧\nوقيل: بل أولياؤه هم المخوفون، وذاك أن الناس ضربان:\nضرب لا سبيل للشيطان عليه، وهم المعنيون بقوله: ﴿إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ﴾، وضرب بخلافهم، وهم الذين قال فيهم: (أولياؤهم الطاغوت)، وقد صرح تعالى بذلك في قوله: (فإذا قرأت القرآن فاستعذ بالله من الشيطان الرجيم\nإلى قوله: ﴿إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ﴾⟪16:100⟫.\nوحقيقة خوف الله أمتثال أمره، وعلى هذا\n⟦3:996⟧\nقال: ﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ﴾⟪35:28⟫ ثم قال: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪3:175⟫، تنبيها أن من فرط الإيمان التحقق أن ليس للشيطان سلطان على الذين آمنوا، ومن علم ذلك علم أوامر الله، فاتبعها في ترك ما يأمر به الشيطان."}, {"a": [176], "v": 3, "p": 996, "ev": 3, "ep": 999, "sid": 1197, "t": "قوله تعالى: (ولا يحزنك الذين يسارعون في الكفر إنهم لن يضروا الله شيئا يريد الله ألا يجعل لهم حظا في الآخرة ولهم عذاب عظيم (176)\nكما نهى تعالى عن الخوف مما يتوقع من حزب الشيطان، نهى عن\nالحزن على ما يفوته منهم، ووصف الكفار بالمسارعة في الكفر.\nكما وصف المؤمنين بالمسارعة في الإيمان، فقال: ﴿وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ﴾، وحقيقة المسارعة في ذلك أن يترقى الإنسان فيما يتحراه منزلة فمنزلة، خيرا كان أو شرا، فيتعوده فيتقوى به\n⟦3:997⟧\nعلى المنزلة الثانية، لأن الشر حاصل بعضه عن بعض، وحامل\nبعضه بعضا، وكذا الخير، وعلى هذا قال أمير المؤمنين: تبدو\nنكتة بيضاء في القلب، كلما ازداد الإيمان ازداد البياض، فإذا\nاستكمل الإيمان ابيض القلب كله، وإن النفاق يبدو نكتة سوداء.\nكلما ازداد النفاق ازداد السواد، فإذا استكمل النفاق اسود\nالقلب كله، وبين أن لا يعود إلى الله من مسارعتهم في الكفر\n⟦3:998⟧\nمضرة، كقوله: ﴿وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ﴾.\nإن قيل: كيف جعل العلة في قوله: ﴿وَلَا يَحۡزُنكَ﴾⟪3:176⟫ أنهم لن يضروا\nالله شيئا، ولم يكن المسلمون يحزنون، لأجل أن خطر لهم أن\nهؤلاء يضرون الله، إنما كان حزنهم أن يضروهم؟\nقيل: معنى ذلك لن يضروا أولياءه، ألا ترى أنه - صلى الله عليه وسلم - قال: \"إن الله تعالى يقول: من آذي لي وليا قد آذاني \".\nوعلى التتبيه على هذا المعنى قال: ﴿إِنَّ ٱلَّذِينَ يُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ﴾⟪33:57⟫.\nوقوله: ﴿إِنَّمَا جَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ﴾⟪5:33⟫.\nوقوله: ﴿يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ﴾⟪3:176⟫\n⟦3:999⟧\nيريد إحباط عملهم بما استحقوه من الذنوب.\nوقيل: يريد الحكم بحرمان ثوابهم، وأن لا يجعل\nلهم ما يستحقه المطيعون، والفرق بين السرعة والعجلة إذا\nاعتبرنا بنفس الفعل، هو أن السرعة أن لا يترك الأمر يتأخر عن\nوقته، والعجلة فيه أن يقدمه على وقته، وإذا اعتبرنا بقوى النفس\nفالعجلة ما يفعل على مقتضى الشهوة، والسرعة تقال فيها وفيما\nيفعل على مقتضى الرأي والفكرة، ولذلك ذم العجلة على\nالإطلاق، وقد حمد السرعة في مواضع."}, {"a": [177], "v": 3, "p": 999, "ev": 3, "ep": 1001, "sid": 1200, "t": "قوله تعالى: (إن الذين اشتروا الكفر بالإيمان لن يضروا الله شيئا ولهم عذاب أليم (177)\n⟦3:1000⟧\nقد تقدم حقيقة الشرى والبيع إذا استعملا في الكفر والإيمان.\nوقال كثير من المفسرين: هذه الآية في معنى الأولى، وقد أعيدت\nتأكيدا، والصحيح أن الأول ذم للذين تحروا الكفر وتزايدوا\nفيه متسارعين، وهذا ذم لمن حصل الإيمان فأفرج عنه، واستبدل\nبه كفرا، وهم الذين وصفهم بالارتداد على أعقابهم، وذم لمن\nمكن من الإيمان فرغب عنه، وآثر الكفر عليه، فصار كالبائع\nإيمانه بكفر.\nوقوله: (شيئا) في موضع المصدر، أو تقديره\n⟦3:1001⟧\nبشيء، فحذف الجار ونصبه، وجعل لمن بدل الكفر بالإيمان\nعذابا أليما، وهو أبلغ مما جعله للفرقة الأولى، حيث وصفه\nبالعظم، إذ يقال العظيم اعتبارا بغيره مما هو من جنسه، وقد لا\nيكون شديد الألم، وأليم يقال لما تناهى في الألم، إذ هو بناء\nالمبالغة، ويقال: هو أليم، سواء اعتبر بغيره أو لم يعتبر."}, {"a": [178], "v": 3, "p": 1001, "ev": 3, "ep": 1007, "sid": 1202, "t": "قوله تعالى: (ولا يحسبن الذين كفروا أنما نملي لهم خير لأنفسهم إنما نملي لهم ليزدادوا إثما ولهم عذاب مهين (178)\n⟦3:1002⟧\nالإملاء إطالة المدة، ومنه (واهجرني مليا).\nوتمليت حبيبا، وإملاء الكتاب على أحد القولين، والملوان.\nوإذا قرئ بالياء فسهل، واذا قرئ بالتاء فصعب، فالذين كفروا\nهو المفعول الأول، ولا يصح أن يجعل ﴿أَنَّمَا نُمۡلِي لَهُمۡ﴾⟪3:178⟫ المفعول\nالثاني، لأن هذه الأفعال تدخل على مبتدأ وخبر.\nويجب أن يكون المفعول الثاني هو الأول في المعنى.\nو ﴿أَنَّمَا نُمۡلِي لَهُمۡ﴾⟪3:178⟫ ليس في المعنى (الذين كفروا)، ولا يصح أن يجعل بدلا كما جعل في\n⟦3:1003⟧\nقوله: ﴿وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ﴾⟪18:63⟫.\nوفي قوله: ﴿وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ﴾⟪8:7⟫ فإنه حينئذ يلزم أن ننصب (خيرا) حتى يصير المفعول الثاني، فيجب أن يكون بالياء\nأجود، وقد اختلف في تأويل الآية من حيث إن ظاهرها يقتضي\n⟦3:1004⟧\nأن الله تعالى يريد بإملائهم أن يكفروا.\nقالوا: والله يتعالى عن هذا القصد، مع كون هذه الآية منافية لمقتضى قوله: ﴿وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ﴾⟪51:56⟫\n⟦3:1005⟧\nفمنهم من قال: الآية على التقديم والتأخير.\nوتقديرها: لا يحسبن الذين كفروا أنما نملي لهم ليزدادوا إثما.\nبل إملاؤنا خير لهم، ويكون مفعول (ولا يحسبن)\nهو ﴿إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ﴾⟪3:178⟫، وعلق أن، وجعل ﴿أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ﴾⟪3:178⟫ كالعلة لتأخيرهم، تنبيها أن ذلك أولاهم ليصير معونة\nلاكتسابهم الخير لأنفسهم، وهذا فاسد، لأن إنما يصح أن\nيعلق حيث ما يدخل لام الابتداء في خبره، ومنهم من قال:\n⟦3:1006⟧\nالكلام على الترتيب، والمفعول هو (أنما) وجعل اللام لام\nالعاقبة، وتحقيق لام العاقبة هو أن اللام تارة تجيء تبيينا لقصد\nالفاعل بفعله نحو ﴿وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ﴾⟪51:56⟫.\nوتارة تبيينا لما أدى إليه الفعل، لا لقصد الفاعل، نحو ﴿وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِيرٗا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ﴾⟪7:179⟫.\nإن قيل: لم قال هاهنا: (عذاب مهين)؟\nقيل: لما ذكر هاهنا إملاء الإنسان في الأعراض الدنيوية.\nوذلك قد يكون في الدنيا هوانا وعذابا\n⟦3:1007⟧\nلصاحبه، وهو لفقدان بصيرته يقدر أن الهوان في فقدانه فلا يفرج\nعنه؛ ذكر الهوان الذي هو أعم الألفاظ الثلاثة من (العظيم)\nو (الأليم) و (ألمهين) ليعم الدارين، وعلى هذا قال:\n﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾⟪9:55⟫."}, {"a": [179], "v": 3, "p": 1007, "ev": 3, "ep": 1011, "sid": 1208, "t": "قوله تعالى: (ما كان الله ليذر المؤمنين على ما أنتم عليه حتى يميز الخبيث من الطيب وما كان الله ليطلعكم على الغيب ولكن الله يجتبي من رسله من يشاء فآمنوا بالله ورسله وإن تؤمنوا وتتقوا فلكم أجر عظيم (179)\nالخبيث: مستعار للعمل السيئ، والطيب: للعمل الصالح\n⟦3:1008⟧\nتشبيها للذكر المسموع بالنشر المشموم، وعلى هذا قال الشاعر:\nتبحثت عن أخباره فكأنما. . . نبشت صدأه بعد ثالثة الدفن\nوقال اخر:\n. . . ثناء مثل ريح الجورب\nوعلى هذا حمل (الخبيثات للخبيثين)، (والطيبات للطيبين)\nأي الأعمال في الخبث والطيب جارية مجرى فاعليها، وقيل: المؤمن\nأطيب من عمله، والكافر أخبث، والاجتباء: كالاصطفاء،\n⟦3:1009⟧\nوأصله الجمع، فكأن من اجتباه الله ضمه إلى نفسه حتى يكون له\nبأجمعه، بخلاف من قال: ﴿ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ﴾⟪39:29⟫\nوإلى ذلك الإشارة بقوله: ﴿وَٱصۡطَنَعۡتُكَ لِنَفۡسِي﴾⟪20:41⟫ وتحقيق التمييز من الله لا على سبيل التعرف، بل ليحصل الخبيث خبيثا والطيب طيبا، وذلك حقيقة التكليف، وقد كرر الله تعالى هذا المعنى مع كل فصل، فقال:\n⟦3:1010⟧\n(وليعلم)، (وليبتلي) و، (وليمحص) و (ليميز).\nوقال من بعد: ﴿لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ﴾⟪3:186⟫، كل ذلك\nتنبيها على أن التكليف في الحقيقة هذه الأشياء، وأما الغيب فكل\nما لا تدركه الحواس وبداهة العقول، وهذا على القول\nالمجمل ثلاثة أضرب: ضرب استبد تعالى به ولم يطلع عليه\nأحدا لا الملائكة المقربين، ولا من دونهم، لاستغنائهم عنه.\nوضرب قد يطلع عليه أصفياء عباده، وهو حقائق العلوم، وذلك\nبحسب ما عرف من حاجتهم إليه ومصلحتهم فيه، وإياه عنى\nبقوله: ﴿سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ﴾⟪7:146⟫.\nوبين في الآية أن اطلاع العامة على غيبه وأقضيته\n⟦3:1011⟧\nمناف للحكمة، وذلك أن جماعة من الكفار سألوا النبى - صلى الله عليه وسلم - وقالوا: هل نحن ممن يؤمن؟\nثم قال: ﴿فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ﴾⟪3:179⟫ تنبيها\nعلى التوكل على الله وحسن الظن بنبيه، والتحقق أنه يفعل بعباده\nما هو أصلح لهم، وأن بالإيمان والتقوى يستحق الأجر العظيم."}, {"a": [180], "v": 3, "p": 1011, "ev": 3, "ep": 1014, "sid": 1212, "t": "قوله تعالى: (ولا يحسبن الذين يبخلون بما آتاهم الله من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيامة ولله ميراث السماوات والأرض والله بما تعملون خبير (180)\nقرئ بالياء على تقدير: لا يحسبن الباخلون البخل هو خير\n⟦3:1012⟧\nلهم، فحذف البخل الذي هو المقعول الأول، لدلالة (يبخلون)\nعليه، كقولك: من كذب كان شرا له، وإذا قرئ بالتاء فتقديره\nلا تحسبن بخل الذين يبخلون هو خيرا لهم، فحذف المضاف\nلظهور المعنى، وبين بالآيتين أنهم جعلوا أعمارهم وأموالهم\nمصروفة إلى ما أورثهم إثما أو عقوبة يوم القيامة، وتطويقهم ما\nبخلوا به على طريق التشبيه والتقريب، نحو ما ذكر النبي - صلى الله عليه وسلم - \"يأتي كنز أحدهم يوم القيامة شجاعا أقرع، له زبيبتان، فيطوق\nفي حلقه،\n⟦3:1013⟧\nفيقول: أنا الزكاة التى منعتني \".\nوعلى هذا قوله تعالى: ﴿وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ﴾⟪9:34⟫ إلى قوله: ﴿فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ﴾⟪9:35⟫، ونبه بقوله: ﴿وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ﴾⟪3:180⟫ على انتقال ما في أيديهم إليه، كما قال:\n﴿وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ﴾⟪6:94⟫، ونبه أن ما خولهم\nلو أنفقوا على ما يجب وكما يجب لاستحقوا ثوابا، فلما لم يفعلوا\nذلك انتقل عنهم، وصار عقوبة لهم، وكأنه إلى مقتضى معناه\nأشار من أوصى، فقال: اكتبوا هذا ما خلف فلان يسوءه وبنوه\n⟦3:1014⟧\nانتقل عنه نفعه، وخفي عليه وزره، وبين أنه عالم ببخلهم، وما\nيؤول إليه حالهم، وما يخبرهم به."}, {"a": [181], "v": 3, "p": 1014, "ev": 3, "ep": 1018, "sid": 1215, "t": "قوله تعالى: (لقد سمع الله قول الذين قالوا إن الله فقير ونحن أغنياء سنكتب ما قالوا وقتلهم الأنبياء بغير حق ونقول ذوقوا عذاب الحريق (181)\nلما أنزل الله ﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا﴾ قال قوم من\nاليهود تهكما على النبي - صلى الله عليه وسلم -: إن الله فقير ونحن أغنياء، يستقرض منا، فأنزل الله تعالى ذلك، ولم يعيرهم أنهم اعتقدوا فقر الله.\nوإنما عيرهم تجاهلهم وتكذيبهم وصرفهم الكلام إلى غير الوجه المقصود به، وعلى هذا قوله: ﴿وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ﴾⟪5:64⟫.\n⟦3:1015⟧\nونبه بقوله: ﴿وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ﴾⟪3:181⟫ أنهم ارتكبوا\nمن المعاصي ما هو مثل هذا القول، أو أكثر منه، ولم يقل (بغير\nحق): أن في قتل بعض الأنبياء حقا، ولكن جعل ذلك حالهم\nعلى العموم، أي هو في كل حال على غير حق، وكتب ذلك\nقيل: هو على الحقيقة، وقيل: هو على طريق المثل، عبارة عن\nحفظه، وأنه لا ينسى، واعلم أن الكتابة جعلها الله لنا عونا\n⟦3:1016⟧\nلحفظنا، وذاك أن اللفظ لا يفهم إلا القريب دون البعيد، وإلا\nالشيء بعد الشيء، ويسرع إليه مع ذلك الاضمحلال، فربما لا يعيه\nالسمع، وإذا وعاه فربما لم يتصوره، وإذا تصوره فربما أخل به\nالحفظ فأعانه الله بالكتابة، لتكون تكملة لقوة النطق، وواعية لما\nيضيع من الفهم، ومدركة جملة في حالة واحدة، فعلم من ذلك\nأن الكتابة وإن كانت شريفة فإنما احتجنا إليها لنقصنا وتكميل\nأفهامنا، فمن حمل الكتابة على الحقيقة قال: كتب الملأ الأعلى\nأعمالنا، لا لجبران نقصهم وضعف فهمهم وخوف نسيانهم؛ ولكن\nلجبران نقيصة البشر، وليتذكر به ما لعله نسي، وليرى صورة\nأعماله المتفرقة دفعة، ومن حمله على التشبيه فإنه ذكر أن نقص\nالقريحة والسهو والنسيان الموجودة فينا في الدنيا معدومة عنا في\nالآخرة؛ فلا حاجة بنا إلى الكتابة، وحينئذ قال: وعلى ذلك وصف\nالكتابة بالنطق في قوله: ﴿هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيۡكُم بِٱلۡحَقِّۚ﴾⟪45:29⟫.\nوقوله: ﴿وَكَتَبۡنَا لَهُۥ فِي ٱلۡأَلۡوَاحِ مِن كُلِّ شَيۡءٖ﴾⟪7:145⟫ وعلى هذا سمى\n⟦3:1017⟧\nالوحي كتابا، فقال: ﴿وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ﴾، ومعلوم أن\nالمنزل لم يكن وقت الإنزال مكتوبا، قال: وعلى هذا معنى قوله:\nتعالى ﴿كِرَامٗا كَٰتِبِينَ﴾⟪82:11⟫ أي حافظين، وقال: ﴿بِأَيۡدِي سَفَرَةٖ﴾⟪80:15⟫.\nقال: وعلى هذا قول الشاعر:\nصحائف عندي للعتاب طويتها. . . ستنشر يوما والعتاب يطول\nوهذا القول وإن كان له مساغ في مجاز اللغة، فأهل الأثر\nعلى الوجه الأول، والله أعلم بحقائق أحوال القيامة، ومعنى\n⟦3:1018⟧\n(ونقول ذوقوا) أي نذوقهم ذلك، ونوجب لهم."}, {"a": [182], "v": 3, "p": 1018, "ev": 3, "ep": 1020, "sid": 1219, "t": "قوله تعالى: (ذلك بما قدمت أيديكم وأن الله ليس بظلام للعبيد (182)\nأي نكتب ما قالوا ونعاقبهم عليه جزاء لما ارتكبوه.\nإن قيل: لم خص اليد، وفيما ذكره عنهم أفعال بغيرها من الجوارح؟\n⟦3:1019⟧\nقيل: لما كانت اليد هي الآلة الصانعة المختصة بالإنسان، فإنه لما\nكفى كل واحد من الحيوانات بما احتاج إليه من الأسلحة\nوالملابس، وسخره لاستعمالها في الدفع عن نفسه، وخلق\nالإنسان عاريا من كل ذلك، جعل له الرؤية واليد الصانعة.\nليعلم برؤيته، وليعمل بيده فوق ما أعطى الحيوانات، فلما كان\nلليد هذه الخصوصية صارت تخص بإضافة عمل الجملة إليها.\nإن قيل: لم خص لفظ ظلام الذي هو للتكثير في نفي\nالظلم في هذا المكان، ولم يقل على ما قال في قوله: ﴿لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ﴾⟪4:40⟫، الذي هو يقتضي نفي الظلم قليله وكثيره؟\nقيل: إنما خص ذلك لأنه لما كان في الدنيا قد يظن بمن يعذب غيره عذابا\n⟦3:1020⟧\nشديدا أنه ظلام قبل أن يفحص عن حال جرمه، بين تعالى\nذنبهم، وأنه إذا عاقبهم عقوبة شديدة فليس بظلام لهم، وإن كان\nقد يظن في الدنيا بمن يفعل ذلك أنه ظلام . تعالى الله عن الظلم."}, {"a": [183], "v": 3, "p": 1020, "ev": 3, "ep": 1022, "sid": 1221, "t": "قوله تعالى: (الذين قالوا إن الله عهد إلينا ألا نؤمن لرسول حتى يأتينا بقربان تأكله النار قل قد جاءكم رسل من قبلي بالبينات وبالذي قلتم فلم قتلتموهم إن كنتم صادقين (183)\nالقربان: أصله مصدر كالشكران والكفران، وفي التعارف\n⟦3:1021⟧\nاسم لما يتقرب به إلى الله تعالى، وكثر استعماله في\nالنسيكة، والعهد كالعقد، ولما تعورف في الوصية والأمر.\nكثر استعماله مع: إلى، فقيل: عهد إليه، ولما ادعى اليهود\nعلى ما أوقع شبهة للجهلة، وكان حلها يصعب عليهم على\nالتحقيق، وربما كان اليهود مع ذلك يشغبون فيه، سلم\nدعواهم كتسليم جدل وناقضهم فيها، وكأنه قيل:\n⟦3:1022⟧\nهب الأمر كما قلتم أليس من الحق أن لا تقتلوا من الأنبياء من جاءكم\nبالبينات وبالذي قلتم، وإذا قتلتموهم ولم تقبلوا قولهم، دل\nذلك أنكم كاذبون في دعواكم؟ أنه عهد إلينا بذلك، فهذا معنى\nقوله: ﴿فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ﴾⟪3:183⟫، وهذا أوضح\nدلالة وأقربها مأخذا وأخزاها لهم."}, {"a": [184], "v": 3, "p": 1022, "ev": 3, "ep": 1025, "sid": 1223, "t": "قوله تعالى: (فإن كذبوك فقد كذب رسل من قبلك جاءوا بالبينات والزبر والكتاب المنير (184)\nإن قيل: لم قال: ﴿وَٱلزُّبُرِ وَٱلۡكِتَٰبِ﴾⟪3:184⟫ والزبور هو الكتاب.\nلقول الشاعر:\n. . . . . . . . . . . . . . . . . . . . . . . . كخط زبور عسيب يمان\n⟦3:1023⟧\nقيل: قد قال بعضهم: الزبور هو الكتاب المقصور على الحكمة\nالعقلية دون الأحكام الشرعية، والكتاب في تعارف القرآن\nما يتضمن الأحكام، ولهذا جاء في عامة القرآن كتاب وحكمة.\nففصل يينهما لهذا، واستعمل الكتابة في معنى الإيجاب، فعلى هذا\nاشتقاقه من زبرت الشيء أي حكمته.\nوقيل: الزبور اسم لما أجمل ولم يفصل، والكتاب يقال لما قد فصل.\nقيل: واشتقاقه من الزبرة أي القطعة من الحديد التي تركت بحالها.\nوعلى هذا قال الشاعر:\n⟦3:1024⟧\nوما السيف إلا زبرة لو تركتها. . . على الحالة الأولى لما كان يقطع\nوقيل: الزبور ها هنا اسم للزاجر من قولهم: زبرته أي زجرته.\nقال: وبين أنه تعالى أتاهم بالآيات الدالة على الوحدانية والنبوة.\nوبالمزاجر المعنية بقوله: ﴿فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ﴾⟪6:42⟫\nوهذا تسلية للنبي - صلى الله عليه وسلم - وعتاب له.\nفقد روي أنه قال: \"ما لقي أحد في الله ما لقيت\".\nفنبه أن حال الأنبياء قبله كحاله، وحال أقومهم كحال قومه، وليس الشرط في نحو هذا الموضع للشك، كما تصوره بعض المفسرين، فأخذ يتخبط في جوابه، وإنما ذلك\n⟦3:1025⟧\nللتحقيق، ومورده كقياس شرطي موجب للحكم، وبيانه\nإن كذبوك فقد كذبوا من صدقك، وقد صدقك الرسل قبلك.\nفإذا كذبوك فقد كذبوا رسلا من قبلك."}, {"a": [185], "v": 3, "p": 1025, "ev": 3, "ep": 1028, "sid": 1226, "t": "قوله تعالى: (كل نفس ذائقة الموت وإنما توفون أجوركم يوم القيامة فمن زحزح عن النار وأدخل الجنة فقد فاز وما الحياة الدنيا إلا متاع الغرور (185)\nالفوز،: إدراك الأمنية. والمفازة في قوله: ﴿فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ﴾⟪3:188⟫ مصدر، ويقال للمهلكة: مفازة تفاؤلا، والصحيح أنهم لما رأوها تارة سببا للفوز، وتارة سببا للهلاك سموها بالاسمين، وذلك بنظرين مختلفين، وكذا قولهم: هلك، وفاز، إذا مات،\n⟦3:1026⟧\nكأنه رئي الموت في بعض الناس هلاكا له، وفي بعضهم فوزا\nله، إما لكونه متبلغا بذلك إلى فوز الآخرة ونعيم الأبد.\nوإما لخلاصهم من شدة يرى الموت في جنبها فوزا.\nوكذا النية أراها والأمنية من أصل واحد بنحو هذين النظرين.\nوتخصيص الذوق هاهنا من حيث إنه ذكر الباخلين بالمال.\nوهو قوله: ﴿وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ﴾⟪3:180⟫ الآية.\nوأعظم البخل بالمال يكون خشية من فقدان الطعام الذي به قوام الأبدان، ولهذا ذكر\n⟦3:1027⟧\nألأكل في عامة المواضع التي ذكر فيها احتجاز المال، نحو ﴿وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم﴾⟪2:188⟫، وقوله: ﴿إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ﴾⟪4:10⟫ فبين بالذوق أن الذي يخافونه طعام لابد منه، والغرور: مصدر أو جمع غار، كرقود، وقعود، في\nجمع راقد وقاعد، والمتاع: التمتع،\n⟦3:1028⟧\nفنبه أن السكون إلى الدنيا والتمتع بها غرور، وأن الكيس من دان\nنفسه وعمل لما بعد الموت، واقتصر على زاد يتبلغ به."}, {"a": [186], "v": 3, "p": 1028, "ev": 3, "ep": 1031, "sid": 1229, "t": "قوله تعالى: (لتبلون في أموالكم وأنفسكم ولتسمعن من الذين أوتوا الكتاب من قبلكم ومن الذين أشركوا أذى كثيرا وإن تصبروا وتتقوا فإن ذلك من عزم الأمور (186)\nقيل: سبب نزولها أن كعب بن الأشرف كان يهجو النبي - صلى الله عليه وسلم -\n⟦3:1029⟧\nويحرض المشركين عليه حتى قتله محمد بن مسلمة.\nوقيل: بل هو أن سمع أبو بكر يهوديا يقول: ترى إله محمد فقيرا\nحتى يستقرض منا، فلطمه أبو بكر، وجملة الأمر أن جميع\nما يبتلى به الإنسان ويتعبد به ثلاثة أشياء: إما متعلق بالمال.\nوإما بالنفس، وإما بمجاهدة العدو، وأعظم المجاهدة الصبر\n⟦3:1030⟧\nعلى الأذى المسموع من الأعداء، إذ هو سبب الشرور، ولهذا\nقال الشاعر:\n. . . وإن الحرب أولها كلام\nفبين تعالى أنكم إن صبرتم - واتقيتم في هذه الأمور التي تبلون\nبها، فإن ذلك من عزم الأمور.\nإن قيل: ما معنى: من عزم الأمور، وما الأمور التي جعل تعالى هذه الأشياء من عزمها؟\nقيل: العزم: ثبات الشيء على الشيء، وإمضاؤه، والحزم\nيقاربه، إلا أن العزم بالإمضاء أشبه، إذ هو من العزم،\n⟦3:1031⟧\nأي القطع، والحزم بجمع الرأي أشبه، إذ هو من حزمت الحطب\nوالقصب، أي جمعت، ولذلك قيل،: أحزم لو أعزم.\nوأما الأمور التي عناها فيجوز أنها الثواب الذي جعل للصابرين\nوالصالحين والمتقين، وما أشبه ذلك، ويجوز أن تكون الأمور\nإشارة إلى ما تقدم، ونبه أن بالصبر والتقوى يتوصل إليه."}, {"a": [187], "v": 3, "p": 1032, "ev": 3, "ep": 1033, "sid": 1233, "t": "قوله تعالى: (وإذ أخذ الله ميثاق الذين أوتوا الكتاب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا فبئس ما يشترون (187)\nالنبذ: طرح الشيء لقلة الاعتداد به، وقولهم: جعلت كذا\nخلف ظهري أي أهملته.\nوقيل: تقدير الآية على ما يقرب من فهم العامة.\nوإذ نبذ أهل الكتاب وراء ظهورهم ما أخذ الله عليهم من الميثاق من تبيين ما أوتوه من الكتاب للناس، واشتروا به ثمنا قليلا، وقد تقدم الكلام في أخذ الميثاق عليهم، وكيفية ذلك\n⟦3:1033⟧\nوفي معاني الثمن القليل."}, {"a": [188], "v": 3, "p": 1033, "ev": 3, "ep": 1037, "sid": 1234, "t": "قوله تعالى: (لا تحسبن الذين يفرحون بما أتوا ويحبون أن يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازة من العذاب ولهم عذاب أليم (188)\nالمفازة من العذاب: هي المنجاة في قول الشاعر:\nتحل بمنجاة من اللوم بيتها. . .\nوالكلام في تكرير (لا تحسبن)، ودخول \"الفاء في الأخير\n⟦3:1034⟧\nمنه صعب، وقد قال الزجاج: لا تحسبن، مكرر لطول القصة.\nقال: والعرب تعيده إذا طالت القصة حسبت وما أشبهها.\nإعلاما أن الذي جرى متصل بالأول، تقول: لا تظنن زيدا إذا\nجاءك وكلمك بكذا فلا تظننه صادقا.\nوقيل: الفاء زائدة.\nوالوجه في ذلك عندي أن قوله: ﴿لَا تَحۡسَبَنَّ﴾⟪3:188⟫ على الخبر وتقدير\nالكلام فيه، وذلك إشارة إلى يوم القيامة بعد أن يدخل الكفار\nالنار، ويقال لهم: ﴿ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ﴾⟪23:108⟫\nوالمعنى: والله إنك لا تحسبهم حينئذ أنهم بمفازة من العذاب.\nأي لهم سبيل إلى الخلاص فلا تحسبنهم الآن، وهذا نهي والأول خبر،\n⟦3:1035⟧\nوحذف مفعول أحد الفاعلين، وإذا قرئ بالياء، فكذلك، ويكون\nبتقديره: لا تحسبن أنفسهم كذلك.\nوالآية قيل: نزلت في قوم دخلوا على النبي - صلى الله عليه وسلم - فنافقوه، فلما خرجوا، أثنى عليهم بعض الناس ففرحوا بذلك.\nوقيل: نزلت في الذين كتموا أمر النبي - صلى الله عليه وسلم - وادعوا علما وعبادة أثنى عليهم بها قومهم،\n⟦3:1036⟧\nوقيل: نزلت في المنافقين المتخلفين عن الجهاد، المدعين دعاوى يحبون\nأن يحمدوا عليها، وكيف ما كان. فالآية عامة في النهي عن\nالرياء والتشبع، والذم لمن فعل خيرا ففرح به، وإلحاق الوعيد\nبمن أحب أن يحمد بما لم يفعل.\nوقد روي أن إبليس قال: إذا ظفرت من ابن آدم بثلاث لم أطالبه بغيرها:\nإذا أعجب بنفسه،\n⟦3:1037⟧\nواستكثر عمله، وسر بمدحه بما لم يفعله.\nإن قيل: - فكيف قال عليه السلام: \"من سرته حسنته\nوساءته سيئته فهو مؤمن \"؟\nقيل: السرور بذلك محمود، والفرح به مذموم.\nوقد تقدم الفرق بينهما، وبين بقوله: ﴿وَلَهُمۡ عَذَابٌ أَلِيمٞ﴾⟪3:188⟫\nمع أنهم لا ينجون، فإنهم يعذبون عذابا أليما."}, {"a": [189, 190], "v": 3, "p": 1037, "ev": 3, "ep": 1041, "sid": 1238, "t": "قوله تعالى: (ولله ملك السماوات والأرض والله على كل شيء قدير (189)\n⟦3:1038⟧\nأتبع تكذيبهم فيما قالوا: إن الله فقير. وتبكيتهم\nفيما فعلوه، وما وعدهم به من العذاب بما أنبأ\nعن قدرته عز وجل وسعة ملكه.\nوأن لا سبيل لهم إلى النجاة وإلى الخروج\nعن ملكه وسلطانه، وهذا هو المعنى\nالذي تحراه النابغة بقوله:\nفإنك كالليل الذي هو مدركي. . .\nلكن على الآية رونق الإلهية وتعميم الملك والقدرة بلا مثنوية.\nوإضافة الفعل إلى موجد الليل والنهار.\nقول تعالى: (إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات لأولي الألباب (190)\n⟦3:1039⟧\nنبه تعالى أن التفكر في ذلك يدل على وحدانية الله تعالى، وأن\nجميع هذه الأشياء لا تنفك من ثلاثة أضرب:\nإما موجود العين، قائم الجوهر، قابل للانتقال\nوتبذل الأمكنة بأجزائه: كالسماء والنجوم.\nوإما قابل للاستحالة والتغير بجملته وأجزائه.\nوذلك كالأرض وما عليها، وإما أن يكون مما لا بقاء له بحاله.\nبل ينصرم، ويقابله نظيره كالليل والنهار، وقد ذكر ثلاثتها.\nونبه على حدوثها، لأن المتنقل لا ثبات له، والمستحيل لا بقاء له.\nوما كان هذا حاله فغير منفك من دلالة الحدث، وما لم يخل من\nمحدث فمسخر له، ومحال أن يكون المسخر المحدث أزليا واجب\nالوجود، فإذن لابد له من موجد يوجده، وموجده واجب\nالوجود، وذلك هو الباري تعالى، ﴿وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ﴾.\n⟦3:1040⟧\nونبه بقوله: ﴿لِّأُوْلِي ٱلۡأَلۡبَٰبِ﴾⟪3:190⟫ أن من لم يكن ذا لب قل عناؤه في التفكر فيها، واللب هو اسم للعقل أزيل عنه الدرن، وذاك أن العقل وإن كان أشرف\nمدرك من الأشياء فهو في الأصل كسيف حديد لم يطبع ولم يصقل.\nفإذا تفقد وتعهد بالحكمة صار كسيف طبع، فأزيل خبثه، وشحذ\nحده، وكل موضع يذكر الله تعالى فيه أجل مدرك لا يمكن إدراكه\nإلا بأجل مدرك.\nقال بعض الصوفية: هذه المنزلة وإن خص بها أولوا الألباب فمنزلة الأنبياء والأولياء أشرف منها، لأنهم ينظرون من خالق السموات والأرض إليها، ولهذا قال لنبيه - صلى الله عليه وسلم -\n⟦3:1041⟧\n﴿أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ﴾⟪25:45⟫، وهذا الذي قاله صحيح.\nفإن الإنسان يمكنه أن يعرف حكمة الصانع أولا بتدبر\nمصنوعه، ومتى عرف حكمة الصانع حينئذ عرف مصنوعاته\nبه، فيصير ما كان دالا مدلولا، وما كان مدلولا دالا، وبهذا\nالنظر قال من سئل: بم عرفت الله؟ فقال: به عرفت كل ما\nسواه."}, {"a": [191], "v": 3, "p": 1042, "ev": 3, "ep": 1046, "sid": 1243, "t": "قوله تعالى: (الذين يذكرون الله قياما وقعودا وعلى جنوبهم ويتفكرون في خلق السماوات والأرض ربنا ما خلقت هذا باطلا سبحانك فقنا عذاب النار (191)\nالذكر: ذكر باللسان، وذكر بالقلب.\nوذكر القلب ذكران: ذكر عن نسيان ، وهو إعادة ما انحذف عن الحفظ، وذلك هو التذكر في الحقيقة، وذكر هو إدامة مراعاة ما ثبت في الحفظ.\nوقوله: ﴿وَعَلَىٰ جُنُوبِهِمۡ﴾⟪3:191⟫ عبارة عن حال الاضطجاع، وعلى\nذلك قوله: ﴿وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا﴾⟪10:12⟫\nفمن حمل الآية على الصلاة، وقال: معناه لا يخلون بها\nفي شيء من أحوالهم قائمين إذا قدروا، قاعدين إذا عجزوا،\n⟦3:1043⟧\nوعلى جنوبهم إذا مرضوا.\nوقد روي في ذلك أن النبي - صلى الله عليه وسلم - قال لسهل بن حنيف: \"صل قائما، فإن لم تستطع فقاعدا، فإن لم تستطع فعلى جنب \".\nثم تلا الآية، ومنهم من جعله أعم من\n⟦3:1044⟧\nذلك، وقال: لا ينفكون من ذكر الله في جميع أحوالهم.\nكقولك: ﴿رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ﴾⟪24:37⟫.\nومنهم من جعله أعم من ذلك أيضا، وقال: معناه لا يتحرون بجميع\nأفعالهم إلا وجهه، وبيان ذلك أن مباحات أولياء الله كلها\nقرب يستحق بها الثواب، وذاك أنهم لا يأكلون ولا ينامون إلا\nوقت الضرورة، ومقدار ما يستعينون به على العبادة، وما لا تتم\nعبادتهم إلا به فذاك واجب كوجوبها.\nوذلك قوله ﴿وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ﴾⟪3:191⟫ إشارة إلى ما قال - صلى الله عليه وسلم -:\n⟦3:1045⟧\n\"تفكروا في آلاء الله، ولا تفكروا في الله \".\nوقوله: ﴿رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا﴾⟪3:191⟫\nأي يقولون وليس يعني بذلك القول من دون العلم.\nفإن ذلك إقامة شهادة، ومن شهد بشيء وهو على ما\nشهد به، لكن لا يعلم كونه كذلك فشهادته مردودة بدلالة\nقوله: ﴿إِلَّا مَن شَهِدَ بِٱلۡحَقِّ وَهُمۡ يَعۡلَمُونَ﴾⟪43:86⟫.\nومن عرف حقيقة ذلك وأقام هذه الشهادة فكأنهم شهدوا الله وهو يخلق\n⟦3:1046⟧\nالسموات، ولهذا قال تعالى في ذم الكفار حيث ثكلوا هذه\nالفضيلة، فقال: ﴿مَّآ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ﴾⟪18:51⟫ وفي قوله: ﴿رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا﴾⟪3:191⟫ تنبيه أنه قصد تعالى بخلق هذه الأشياء قصدا صحيحا.\nوذلك ما قاله الحكماء أن القصد بخلق السموات والأرض\nإنما هو الإنسان، وإنما خلق النبات والحيوانات قواما له.\nقال: ﴿خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا﴾⟪2:29⟫.\nوالقصد بخلق الإنسان أن يستخلفه في الأرض، فيقوم بحق الخلافة.\nويبلغ بها إلى أعظم السعادة في جواره.\nوعلى ذلك قال تعالى: ﴿وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا بَٰطِلٗاۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُواْۚ﴾⟪38:27⟫، فلما تحقق المتفكرون ما لأجله خلقت السموات والأرض، وعرفوا مآلهم سبحوه، واستعاذوا به من النار."}, {"a": [192], "v": 3, "p": 1047, "ev": 3, "ep": 1048, "sid": 1248, "t": "قوله تعالى: (ربنا إنك من تدخل النار فقد أخزيته وما للظالمين من أنصار (192)\nيقال: خزي الرجل: إذا لحقه انكسار.\nإما من نفسه بإفراط، يقال في مصدره الخزاية.\nوإما من غيره، ويقال في مصدره الخزي.\nوعلى هذا هان وذل، متى كان ذلك من نفسه.\nيقال له الهون والذل، ومتى كان من غيره يقال له الهوان والذل،\n⟦3:1048⟧\nوالآية من تمام الحكاية عن المتفكرين في خلق السموات والأرض."}];
